local isConfiguredScriptOwner, isConfiguredPremiumUser, isScriptOwner, isPremiumUser, hasAdminAccess, isProtectedFromLocalPlayer, getPlayerTargetCode, checkSavedBanState, saveBanStateToDisk, showOwnerScreenBanner, clearPersistentBanner
;(function()
local BAN_FILE_NAME = "CocoPowder_ScriptBanLock.txt" 
do
    local OWNER_UID_SET, OWNER_NAME_SET = {}, {}
    for _, id in ipairs(SCRIPT_OWNERS.UserIds) do
        local n = tonumber(id)
        if n then OWNER_UID_SET[n] = true end
    end
    for _, nm in ipairs(SCRIPT_OWNERS.Usernames) do
        local clean = tostring(nm):lower():gsub("^%s*@+%s*", "")
        if clean ~= "" then OWNER_NAME_SET[clean] = true end
    end

    local PREMIUM_UID_SET, PREMIUM_NAME_SET = {}, {}
    for _, id in ipairs(PREMIUM_USERS.UserIds) do
        local n = tonumber(id)
        if n then PREMIUM_UID_SET[n] = true end
    end
    for _, nm in ipairs(PREMIUM_USERS.Usernames) do
        local clean = tostring(nm):lower():gsub("^%s*@+%s*", "")
        if clean ~= "" then PREMIUM_NAME_SET[clean] = true end
    end

isConfiguredScriptOwner = function(plr)
    if not plr then return false end
    local uid = plr.UserId
    if OWNER_UID_SET[uid] then return true end
    local uname = (plr.Name or ""):lower()
    if OWNER_NAME_SET[uname] then return true end
    if tonumber(_G.COCO_OWNER_ID) == uid then return true end
    if typeof(_G.COCO_OWNER_NAME) == "string" and _G.COCO_OWNER_NAME ~= "" then
        local gNm = _G.COCO_OWNER_NAME:lower():gsub("^%s*@+%s*", "")
        if uname == gNm then return true end
    end
    if typeof(_G.COCO_OWNER_IDS) == "table" then
        for _, id in ipairs(_G.COCO_OWNER_IDS) do
            if tonumber(id) == uid then return true end
        end
    end
    if typeof(_G.COCO_OWNER_NAMES) == "table" then
        for _, nm in ipairs(_G.COCO_OWNER_NAMES) do
            local targetNm = tostring(nm):lower():gsub("^%s*@+%s*", "")
            if targetNm ~= "" and uname == targetNm then
                return true
            end
        end
    end
    return false
end

isConfiguredPremiumUser = function(plr)
    if not plr then return false end
    if isConfiguredScriptOwner(plr) then return true end
    local uid = plr.UserId
    if PREMIUM_UID_SET[uid] or OwnerAdminState.sessionPremiumUsers[uid] then return true end
    local uname = (plr.Name or ""):lower()
    if PREMIUM_NAME_SET[uname] then return true end
    if typeof(_G.COCO_PREMIUM_IDS) == "table" then
        for _, id in ipairs(_G.COCO_PREMIUM_IDS) do
            if tonumber(id) == uid then return true end
        end
    end
    if typeof(_G.COCO_PREMIUM_NAMES) == "table" then
        for _, nm in ipairs(_G.COCO_PREMIUM_NAMES) do
            local targetNm = tostring(nm):lower():gsub("^%s*@+%s*", "")
            if targetNm ~= "" and uname == targetNm then
                return true
            end
        end
    end
    return false
end
end

isScriptOwner = function(plr)
    -- Role authority is allowlist-only; replicated animation beacons are spoofable.
    return plr ~= nil and isConfiguredScriptOwner(plr)
end

isPremiumUser = function(plr)
    -- Never promote an unlisted player because of a client-visible animation/speed.
    return plr ~= nil and isConfiguredPremiumUser(plr)
end

-- Admin Panel is strictly usable ONLY by the Owner (shivyy73) and configured/session Premium Users!
hasAdminAccess = function(plr)
    if not plr then return false end
    return isScriptOwner(plr) or isPremiumUser(plr)
end

-- Privilege hierarchy check:
--   • Owner (shivyy73) outranks everyone, gets the Admin Panel, and is the ONLY user with immunity (cannot be targeted/frozen/banned).
--   • Premium Users get the Admin Panel and overhead tag, but do NOT get immunity.
isProtectedFromLocalPlayer = function(targetPlr)
    if not targetPlr then return false end
    if isScriptOwner(targetPlr) then
        return true
    end
    if not isScriptOwner(LP) and OwnerAdminState.syncedVipIds and OwnerAdminState.syncedVipIds[targetPlr.UserId] then
        return true
    end
    return false
end

getPlayerTargetCode = function(plr)
    if not plr then return 0 end
    return (math.abs(plr.UserId) % 899) + 100 -- Deterministic 3-digit code (100..998)
end

-- Check persistent script ban state
checkSavedBanState = function()
    if _G.COCO_POWDER_BANNED == true then return true end
    local banned = false
    pcall(function()
        if typeof(isfile) == "function" and typeof(readfile) == "function" and isfile(BAN_FILE_NAME) then
            local content = tostring(readfile(BAN_FILE_NAME) or "")
            if content:find("BANNED", 1, true) then
                banned = true
            end
        end
    end)
    return banned
end

saveBanStateToDisk = function(isBanned, ownerName)
    _G.COCO_POWDER_BANNED = isBanned and true or nil
    pcall(function()
        if isBanned then
            if typeof(writefile) == "function" then
                writefile(BAN_FILE_NAME, "BANNED_BY_" .. tostring(ownerName or "Owner"))
            end
        else
            if typeof(delfile) == "function" and typeof(isfile) == "function" and isfile(BAN_FILE_NAME) then
                delfile(BAN_FILE_NAME)
            elseif typeof(writefile) == "function" then
                writefile(BAN_FILE_NAME, "")
            end
        end
    end)
end

-- Prominent Top Banner for Owner Joins, Freeze Lock, and Script Ban Lock
showOwnerScreenBanner = function(titleText, subText, accentCol, durationSec, persistentKey)
    pcall(function()
        local parentContainer = GuiParent or LP:FindFirstChildOfClass("PlayerGui")
        if not parentContainer then return end

        if persistentKey then
            local existing = parentContainer:FindFirstChild("CocoPowder_" .. persistentKey)
            if existing then existing:Destroy() end
        end

        local bGui = Instance.new("ScreenGui")
        bGui.Name = persistentKey and ("CocoPowder_" .. persistentKey) or "CocoPowderOwnerToast"
        bGui.ResetOnSpawn = false
        bGui.DisplayOrder = 1000005
        bGui.IgnoreGuiInset = true
        bGui.Parent = parentContainer

        local card = Instance.new("Frame")
        card.Size = UDim2.new(0, 360, 0, 62)
        card.Position = UDim2.new(0.5, -180, 0, -80)
        card.BackgroundColor3 = Color3.fromRGB(16, 12, 24)
        card.BackgroundTransparency = 0.04
        card.BorderSizePixel = 0
        card.ZIndex = 1000
        card.Parent = bGui
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 16)

        local st = Instance.new("UIStroke")
        st.Color = accentCol or Color3.fromRGB(255, 215, 70)
        st.Thickness = 1.8
        st.Transparency = 0.1
        st.Parent = card

        local badge = Instance.new("Frame")
        badge.Size = UDim2.new(0, 38, 0, 38)
        badge.Position = UDim2.new(0, 12, 0.5, -19)
        badge.BackgroundColor3 = (accentCol or Color3.fromRGB(255, 215, 70)):Lerp(Color3.fromRGB(20, 16, 30), 0.72)
        badge.BorderSizePixel = 0
        badge.ZIndex = 1001
        badge.Parent = card
        Instance.new("UICorner", badge).CornerRadius = UDim.new(0, 12)

        local icon = Instance.new("TextLabel")
        icon.Size = UDim2.new(1, 0, 1, 0)
        icon.BackgroundTransparency = 1
        icon.Text = "👑"
        icon.TextColor3 = accentCol or Color3.fromRGB(255, 215, 70)
        icon.Font = Enum.Font.GothamBold
        icon.TextSize = 18
        icon.ZIndex = 1002
        icon.Parent = badge

        local tLbl = Instance.new("TextLabel")
        tLbl.Size = UDim2.new(1, -66, 0, 20)
        tLbl.Position = UDim2.new(0, 58, 0, 11)
        tLbl.BackgroundTransparency = 1
        tLbl.Text = titleText or "👑 SCRIPT OWNER IN SERVER"
        tLbl.TextColor3 = accentCol or Color3.fromRGB(255, 215, 70)
        tLbl.Font = Enum.Font.GothamBlack
        tLbl.TextSize = 12
        tLbl.TextXAlignment = Enum.TextXAlignment.Left
        tLbl.TextTruncate = Enum.TextTruncate.AtEnd
        tLbl.ZIndex = 1002
        tLbl.Parent = card

        local sLbl = Instance.new("TextLabel")
        sLbl.Size = UDim2.new(1, -66, 0, 18)
        sLbl.Position = UDim2.new(0, 58, 0, 31)
        sLbl.BackgroundTransparency = 1
        sLbl.Text = subText or ""
        sLbl.TextColor3 = Color3.fromRGB(240, 236, 250)
        sLbl.Font = Enum.Font.GothamMedium
        sLbl.TextSize = 10
        sLbl.TextXAlignment = Enum.TextXAlignment.Left
        sLbl.TextTruncate = Enum.TextTruncate.AtEnd
        sLbl.ZIndex = 1002
        sLbl.Parent = card

        TweenService:Create(card, TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
            Position = UDim2.new(0.5, -180, 0, 22)
        }):Play()

        if durationSec and durationSec > 0 then
            task.delay(durationSec, function()
                if bGui and bGui.Parent then
                    TweenService:Create(card, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                        Position = UDim2.new(0.5, -180, 0, -80)
                    }):Play()
                    task.wait(0.3)
                    if bGui and bGui.Parent then bGui:Destroy() end
                end
            end)
        end
    end)
end

clearPersistentBanner = function(persistentKey)
    pcall(function()
        local parentContainer = GuiParent or LP:FindFirstChildOfClass("PlayerGui")
        if not parentContainer then return end
        local existing = parentContainer:FindFirstChild("CocoPowder_" .. persistentKey)
        if existing then existing:Destroy() end
    end)
end
end)() -- end Owner/Ban helper scope

-- Check whether a CFrame is inside safe playable map bounds for local recovery
-- Supports distant custom realms/islands up to 250,000 studs while rejecting deep void & Y=85,000 Self-Vanish sky pocket
local function isSafePlayableCF(cf)
    if not cf then return false end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return false end
    local voidFloor = math.min(OriginalFPDH + 10, -485)
    if pos.Y <= voidFloor or pos.Y > 500000 then return false end
    if math.abs(pos.Y - 85000) < 1500 then return false end
    if pos.Magnitude > 850000 then return false end
    return true
end

-- Distinguish true lethal void freefall from hidden underground rooms, house interiors, custom realms, or skyboxes!
-- Allows attaching in EVERY place in the server (underground bunkers, high skyboxes, distant teleport maps, etc.).
local function isLethalVoidCF(cf, velocity)
    if not cf then return true end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return true end
    if pos.Magnitude > 950000 then return true end
    local hardFloor = math.min(OriginalFPDH - 25, -600)
    if pos.Y <= hardFloor then return true end
    local vy = velocity and velocity.Y or 0
    local killLine = math.min(OriginalFPDH + 2, -495)
    if pos.Y <= killLine and vy < -135 then return true end
    return false
end

local findFallbackSafeCF, WeldSeekingTarget
WeldSeekingTarget = false
do
    local CachedSpawnLocation = nil
    local LastSpawnScanTick = 0
    -- Seed LastKnownSafeCF immediately on startup & respawn so we never lack a valid origin CFrame
    pcall(function()
        local ch = LP and LP.Character
        local rt = ch and ch:FindFirstChild("HumanoidRootPart")
        if rt and isSafePlayableCF(rt.CFrame) then
            LastKnownSafeCF = rt.CFrame
        end
        if LP then
            LP.CharacterAdded:Connect(function(newChar)
                task.spawn(function()
                    local r = newChar:WaitForChild("HumanoidRootPart", 3)
                    if r and isSafePlayableCF(r.CFrame) then
                        LastKnownSafeCF = r.CFrame
                    end
                end)
            end)
        end
    end)
    findFallbackSafeCF = function()
        if isSafePlayableCF(LastKnownSafeCF) then
            return LastKnownSafeCF
        end
        local myRoot = LP and LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if myRoot and isSafePlayableCF(myRoot.CFrame) then
            return myRoot.CFrame
        end
        if not (CachedSpawnLocation and CachedSpawnLocation.Parent) and (tick() - LastSpawnScanTick > 15.0) then
            LastSpawnScanTick = tick()
            CachedSpawnLocation = workspace:FindFirstChildWhichIsA("SpawnLocation", true)
        end
        local spawnPart = CachedSpawnLocation
        if spawnPart and spawnPart.Parent and isSafePlayableCF(spawnPart.CFrame) then
            return spawnPart.CFrame + Vector3.new(0, 4, 0)
        end
        -- NEVER fallback to a random server player's CFrame (which caused unexpected teleports to random players!)
        return CFrame.new(0, 35, 0)
    end
end

local Anti, moveState, AnimCopySys, RewindSys, CocaSkyDestroyer, hookTargetRespawn, removeOverheadTagForUser, updateOverheadNameTags
local recoverCharacterState, safeReturnFromVoid, syncAllActiveIndicators

local StateManager = {}

function StateManager:StopAllAnimations()
    for _, track in ipairs(PlayedAnims) do
        pcall(function() track:Stop(0) end)
        pcall(function() track:Destroy() end)
    end
    PlayedAnims = {}
end

function StateManager:ResetPhysics(character)
    if not character then return end
    local root = character:FindFirstChild("HumanoidRootPart")
    if root then
        if sethiddenproperty then
            pcall(function() sethiddenproperty(root, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(root, "PhysicsRepRootRef", nil) end)
        end
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end
    pcall(function() LP.ReplicationFocus = nil end)
    local keepNoclip = (moveState and moveState.noclip) == true
    local keepNoTouch = (Anti and Anti.Kill and Anti.Kill.enabled) == true
    local isReanimActive = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
    local hiddenMap = type(_G.hiddenBodyParts) == "table" and _G.hiddenBodyParts or nil
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            part.Anchored = false
            part.Massless = false
            part.CanTouch = not keepNoTouch
            part.CanQuery = true
            pcall(function() part.CustomPhysicalProperties = nil end)
            if not isReanimActive and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
                pcall(function() part.LocalTransparencyModifier = 0 end)
                if part.Name ~= "HumanoidRootPart" and not (hiddenMap and hiddenMap[part.Name]) then
                    if part.Transparency >= 0.95 and (
                        part.Name == "Head" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso"
                        or part.Name:find("Arm") or part.Name:find("Hand") or part.Name:find("Leg") or part.Name:find("Foot")
                        or part.Name == "Handle"
                    ) then
                        pcall(function() part.Transparency = 0 end)
                    end
                end
            end
            if part.Name == "HumanoidRootPart" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso" or part.Name == "Head" then
                part.CanCollide = not keepNoclip
            end
        elseif part:IsA("Decal") and not isReanimActive and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
            if part.Name == "face" and part.Transparency >= 0.95 then
                pcall(function() part.Transparency = 0 end)
            end
        elseif part:IsA("Motor6D") and not isReanimActive then
            pcall(function() part.Enabled = true end)
        end
    end
end

function StateManager:StopFling(skipReturn)
    local wasActive = FlingActive
    local savedOrigin = FlingOriginCF
    if FlingConn then FlingConn:Disconnect(); FlingConn = nil end
    if self.FlingStepConn then self.FlingStepConn:Disconnect(); self.FlingStepConn = nil end
    if LP.Character then
        local myRoot = LP.Character:FindFirstChild("HumanoidRootPart")
        if myRoot and sethiddenproperty then
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootRef", nil) end)
        end
        for _, part in ipairs(LP.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function() part.CustomPhysicalProperties = nil end)
                pcall(function() part.LocalTransparencyModifier = 0 end)
            end
        end
    end
    pcall(function() LP.ReplicationFocus = nil end)
    FlingActive = false
    FlingOriginCF = nil
    if FlingSidePanel then FlingSidePanel.Visible = false end
    local currentCam = workspace.CurrentCamera
    if currentCam and (FlingCamType or FlingCamSubject) then
        pcall(function()
            currentCam.CameraType = FlingCamType or Enum.CameraType.Custom
            local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            currentCam.CameraSubject = myHum or FlingCamSubject
        end)
    end
    FlingCamType = nil
    FlingCamSubject = nil
    FlingCamCF = nil
    if wasActive and not skipReturn and LP.Character then
        LastVoidActionEnd = tick()
        safeReturnFromVoid(LP.Character, savedOrigin)
    elseif wasActive and skipReturn and LP.Character then
        self:ResetPhysics(LP.Character)
    end
    if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
end

function StateManager:Cleanup(keepTarget, switchingWeld)
    if moveState and moveState.Vanish and moveState.Vanish.selfActive then
        pcall(function() moveState.Vanish:StopSelfVanish(true) end)
    end
    if _G.CocaBangActive and type(_G.stopCocaBangLock) == "function" then
        pcall(_G.stopCocaBangLock)
    end
    if RewindSys and RewindSys.rewinding and (RewindSys.Stop or RewindSys.StopRewind) then
        pcall(function() (RewindSys.Stop or RewindSys.StopRewind)(RewindSys) end)
    end
    if moveState and (moveState.fly or moveState.flyLanding) and moveState.stopFlyImmediate then
        pcall(moveState.stopFlyImmediate)
    end
    if CurrentWeld then
        pcall(function() CurrentWeld:Destroy(switchingWeld) end)
        CurrentWeld = nil
    end
    self:StopAllAnimations()
    self:StopFling(switchingWeld)
    if OriginalCameraSubject then
        pcall(function()
            local currentCam = workspace.CurrentCamera
            if currentCam then
                local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                currentCam.CameraSubject = myHum or OriginalCameraSubject
                currentCam.CameraType = Enum.CameraType.Custom
            end
        end)
        OriginalCameraSubject = nil
    end
    if LP.Character and not switchingWeld then
        self:ResetPhysics(LP.Character)
        local root = LP.Character:FindFirstChild("HumanoidRootPart")
        if root and not isSafePlayableCF(root.CFrame) then
            safeReturnFromVoid(LP.Character, LastKnownSafeCF)
        else
            recoverCharacterState(LP.Character, root and root.CFrame or LastKnownSafeCF)
        end
    end
    if not keepTarget then CurrentTarget = nil end
end

local function forcePhysicsState(hum)
    if not hum then return end
    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Physics, true) end)
    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Physics) end)
end

local loadPlayableAnim
do
    local ANIM_VERIFY_TIME = 0.06
    local ANIM_MAX_ATTEMPTS = 2

    local function tryPlayOnce(Animator, animId, hum, priority)
        local cleanDigits = tostring(animId or ""):gsub("%D", "")
        if cleanDigits == "" then return nil, nil, false, nil end
        local anim = Instance.new("Animation")
        anim.AnimationId = "rbxassetid://" .. cleanDigits
        local okLoad, track = pcall(function() return Animator:LoadAnimation(anim) end)
        if not okLoad or not track then anim:Destroy(); return nil, nil, false, nil end
        local pri = priority or Enum.AnimationPriority.Action4
        pcall(function() track.Priority = pri end)
        pcall(function() track.Looped = true end)
        pcall(function() track:AdjustSpeed(1) end)
        forcePhysicsState(hum)
        local okPlay = pcall(function() track:Play(0, 1.0, 1.0) end)
        if not okPlay then
            pcall(function() track:Stop(0) end); pcall(function() track:Destroy() end)
            return nil, nil, false, nil
        end
        return track, anim, true, cleanDigits
    end

    loadPlayableAnim = function(Animator, animId, fallbacks, hum, priority)
        if not Animator or not animId then return nil, nil, nil end
        local cands = {}
        local seen = {}
        local function addCand(v)
            local s = tostring(v or ""):gsub("%D", "")
            if s ~= "" and not seen[s] then
                seen[s] = true
                cands[#cands + 1] = s
            end
        end
        addCand(animId)
        for _, f in ipairs(fallbacks or {}) do addCand(f) end
        for _, id in ipairs(cands) do
            for attempt = 1, ANIM_MAX_ATTEMPTS do
                local track, anim, ok, cleanId = tryPlayOnce(Animator, id, hum, priority)
                if ok then return track, anim, cleanId end
                if anim then pcall(function() anim:Destroy() end) end
                if attempt < ANIM_MAX_ATTEMPTS then RunService.Heartbeat:Wait() end
            end
        end
        return nil, nil, nil
    end
end

local AnimateWasDisabled = false

local function stopDefaultTracks(c)
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local animator = hum:FindFirstChildOfClass("Animator")
    if animator then
        local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
        if ok and tracks then
            for _, t in ipairs(tracks) do
                if not IsCocoBeaconTrack[t] then
                    pcall(function() t:Stop(0) end); pcall(function() t:Destroy() end)
                end
            end
        end
    end
end

local function killAnimate(c)
    if not c then return end
    local animate = c:FindFirstChild("Animate")
    if animate and not animate.Disabled then
        animate.Disabled = true
        AnimateWasDisabled = true
    end
    stopDefaultTracks(c)
end

local function restoreAnimate(c)
    if not AnimateWasDisabled then return end
    if c then
        local animate = c:FindFirstChild("Animate")
        if animate then animate.Disabled = false end
    end
    AnimateWasDisabled = false
end

recoverCharacterState = function(char, safeCF)
    char = char or (LP and LP.Character)
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    local hum  = char:FindFirstChildOfClass("Humanoid")
    pcall(function() LP.ReplicationFocus = nil end)
    if root then
        if sethiddenproperty then
            pcall(function() sethiddenproperty(root, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(root, "PhysicsRepRootRef", nil) end)
        end
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero

        local targetCF = nil
        if isSafePlayableCF(safeCF) then
            targetCF = safeCF
        elseif isSafePlayableCF(root.CFrame) then
            targetCF = root.CFrame
        else
            targetCF = findFallbackSafeCF()
        end

        if targetCF then
            local pos = targetCF.Position
            local _, yYaw, _ = targetCF:ToEulerAnglesYXZ()
            root.CFrame = CFrame.new(pos) * CFrame.Angles(0, yYaw, 0)
        end
    end
    local keepNoclip = (moveState and moveState.noclip) == true
    local keepNoTouch = (Anti and Anti.Kill and Anti.Kill.enabled) == true
    local isReanimActive = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
    local hiddenMap = type(_G.hiddenBodyParts) == "table" and _G.hiddenBodyParts or nil
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            part.Anchored = false
            part.Massless = false
            part.CanTouch = not keepNoTouch
            part.CanQuery = true
            pcall(function() part.CustomPhysicalProperties = nil end)
            if not isReanimActive and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
                pcall(function() part.LocalTransparencyModifier = 0 end)
                if part.Name ~= "HumanoidRootPart" and not (hiddenMap and hiddenMap[part.Name]) then
                    if part.Transparency >= 0.95 and (
                        part.Name == "Head" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso"
                        or part.Name:find("Arm") or part.Name:find("Hand") or part.Name:find("Leg") or part.Name:find("Foot")
                        or part.Name == "Handle"
                    ) then
                        pcall(function() part.Transparency = 0 end)
                    end
                end
            end
            if part.Name == "HumanoidRootPart" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso" or part.Name == "Head" then
                part.CanCollide = not keepNoclip
            end
        elseif part:IsA("Decal") and not isReanimActive and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
            if part.Name == "face" and part.Transparency >= 0.95 then
                pcall(function() part.Transparency = 0 end)
            end
        elseif part:IsA("Motor6D") and not isReanimActive then
            pcall(function()
                part.Enabled = true
                part.Transform = CFrame.identity
            end)
        end
    end
    if moveState and moveState.restoreFlyJoints then
        pcall(function() moveState.restoreFlyJoints(char) end)
    end
    local animate = char:FindFirstChild("Animate")
    if animate and animate.Disabled and CurrentWeld == nil and not WeldSeekingTarget and not (moveState and (moveState.fly or moveState.flyLanding)) and not isReanimActive then
        pcall(function() animate.Disabled = false end)
    end
    AnimateWasDisabled = false
    stopDefaultTracks(char)
    if hum and hum.Health > 0 then
        pcall(function()
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Running) then hum:SetStateEnabled(Enum.HumanoidStateType.Running, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Jumping) then hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Freefall) then hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Landed) then hum:SetStateEnabled(Enum.HumanoidStateType.Landed, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.GettingUp) then hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, true) end
            if hum.PlatformStand then hum.PlatformStand = false end
            if hum.Sit then hum.Sit = false end
            if not hum.AutoRotate then hum.AutoRotate = true end
            local curSt = hum:GetState()
            if curSt == Enum.HumanoidStateType.PlatformStanding
                or curSt == Enum.HumanoidStateType.Ragdoll
                or curSt == Enum.HumanoidStateType.FallingDown
                or curSt == Enum.HumanoidStateType.Seated
                or curSt == Enum.HumanoidStateType.Physics
                or curSt == Enum.HumanoidStateType.Dead then
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end
        end)
    end
    local currentCam = workspace.CurrentCamera
    if currentCam and hum and not SpectatingTarget and not FlingActive then
        pcall(function()
            currentCam.CameraType = Enum.CameraType.Custom
            currentCam.CameraSubject = hum
        end)
    end
end

-- Multi-frame anchored void rescue: aborts immediately if CurrentWeld, WeldSeekingTarget, or FlingActive is running so it NEVER fights target connections!
local RescueGeneration = 0

safeReturnFromVoid = function(char, preferredCF)
    char = char or (LP and LP.Character)
    if not char then return end
    if CurrentWeld ~= nil or WeldSeekingTarget or FlingActive then return end
    local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChildWhichIsA("BasePart")
    local hum  = char:FindFirstChildOfClass("Humanoid")
    local wasInDeepVoid = (not root) or (not isSafePlayableCF(root.CFrame)) or (root.Position.Y <= math.min(OriginalFPDH + 45, -200))
    local resolvedCF = isSafePlayableCF(preferredCF) and preferredCF
        or ((root and isSafePlayableCF(root.CFrame)) and root.CFrame or findFallbackSafeCF())
    local pos = resolvedCF.Position
    local _, yYaw, _ = resolvedCF:ToEulerAnglesYXZ()
    local yLift = wasInDeepVoid and 0.6 or 0
    local cleanCF = CFrame.new(pos + Vector3.new(0, yLift, 0)) * CFrame.Angles(0, yYaw, 0)

    recoverCharacterState(char, cleanCF)
    if not root or not root.Parent then return end

    RescueGeneration = RescueGeneration + 1
    local myRescueGen = RescueGeneration

    if not wasInDeepVoid then
        root.Anchored = false
        return
    end

    task.spawn(function()
        pcall(function()
            root.Anchored = true
            for _ = 1, 2 do
                if not root.Parent or myRescueGen ~= RescueGeneration or CurrentWeld ~= nil or WeldSeekingTarget or FlingActive then
                    break
                end
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                root.CFrame = cleanCF
                RunService.Heartbeat:Wait()
            end
            if root.Parent then
                root.Anchored = false
                if myRescueGen == RescueGeneration and CurrentWeld == nil and not WeldSeekingTarget and not FlingActive then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                    root.CFrame = cleanCF
                end
            end
            if myRescueGen == RescueGeneration and CurrentWeld == nil and not WeldSeekingTarget and not FlingActive then
                if hum and hum.Parent and hum.Health > 0 then
                    if hum.PlatformStand then hum.PlatformStand = false end
                    if hum.Sit then hum.Sit = false end
                    if not hum.AutoRotate then hum.AutoRotate = true end
                end
                local currentCam = workspace.CurrentCamera
                if currentCam and hum and not SpectatingTarget then
                    currentCam.CameraType = Enum.CameraType.Custom
                    currentCam.CameraSubject = hum
                end
            end
        end)
        if not (Anti and Anti.Void and Anti.Void.enabled) and not (Anti and Anti.Kill and Anti.Kill.enabled) and CurrentWeld == nil and not WeldSeekingTarget and not FlingActive then
            pcall(function() workspace.FallenPartsDestroyHeight = OriginalFPDH end)
        end
    end)
end

-- Continuously record LastKnownSafeCF when on safe ground (throttled to 7Hz) & instant auto-rescue/self-heal if stranded in void or invisible
do
    local lastSafeSampleTick = 0
    RunService.Heartbeat:Connect(function()
        if FlingActive or CurrentWeld ~= nil or WeldSeekingTarget or (AnimCopySys and AnimCopySys.active) or (moveState and moveState.Vanish and moveState.Vanish.selfActive) or _G.CocaBangActive or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated())) or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) then return end
        local now = os.clock()
        local inVoidWindow = (Anti and Anti.Void and Anti.Void.enabled) or (tick() - LastVoidActionEnd < 6.0)
        if not inVoidWindow and (now - lastSafeSampleTick < 0.15) then return end

        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end

        local pos = root.Position
        local voidFloor = math.min(OriginalFPDH + 22, -260)
        if pos.Y <= voidFloor or math.abs(pos.Y - 85000) < 3500 or pos.Magnitude > 250000 or pos.X ~= pos.X then
            if inVoidWindow or math.abs(pos.Y - 85000) < 3500 or pos.Y <= math.min(OriginalFPDH + 5, -450) then
                safeReturnFromVoid(char, LastKnownSafeCF)
            end
        elseif now - lastSafeSampleTick >= 0.15 then
            lastSafeSampleTick = now
            local head = char:FindFirstChild("Head")
            if head and head:IsA("BasePart") and head.LocalTransparencyModifier > 0.5 then
                for _, p in ipairs(char:GetChildren()) do
                    if p:IsA("BasePart") then
                        pcall(function() p.LocalTransparencyModifier = 0 end)
                    end
                end
            end
            if not (moveState and (moveState.fly or moveState.flyLanding)) then
                if hum.PlatformStand then
                    pcall(function()
                        hum.PlatformStand = false
                        hum.AutoRotate = true
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        hum:ChangeState(Enum.HumanoidStateType.Running)
                    end)
                end
                local animScr = char:FindFirstChild("Animate")
                if animScr and animScr.Disabled then
                    pcall(function() animScr.Disabled = false end)
                end
            end
            local vel = root.AssemblyLinearVelocity.Magnitude
            local isGrounded = (hum.FloorMaterial ~= Enum.Material.Air) or (LastKnownSafeCF == nil)
            if isSafePlayableCF(root.CFrame) and vel < 95 and isGrounded then
                local _, yYaw, _ = root.CFrame:ToEulerAnglesYXZ()
                LastKnownSafeCF = CFrame.new(pos) * CFrame.Angles(0, yYaw, 0)
            end
        end
    end)
end

local stopWeld -- forward declaration
local findPlayerCharacterAnywhere
local pickTargetRef
local getFlatYawCFrame
local getBestTargetCFrame
local streamAndTeleportToTarget
local markIntentionalTeleport

-- ============================================================================
-- 🛡️ REANIMATION & INVISIBILITY ROBUSTNESS HELPERS (0.00ms ZERO-DELAY AWARE)
--   • Detects & filters desynced HumanoidRootParts (from FE Invisibility, Vanish,
--     or fling reanimations where root is sent to sky Y=85000 or underground Y=-185)
--   • Automatically resolves live reanimation clone rigs & netless physics bodies
--     so the weld NEVER detaches or swings your character away into the void/sky!
-- ============================================================================
local isRefPartValid
local isCharacterNetlessReanimated
local findTargetReanimModel
local isLocalCharAliveOrReanimated
local isValidTargetWorldCF

local function isPartInSafeWorldBounds(p)
    if not (p and p.Parent and p:IsA("BasePart")) then return false, nil end
    local okCF, cf = pcall(function() return p.CFrame end)
    if not okCF or not cf then return false, nil end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return false, nil end
    if pos.Magnitude > 45000 then return false, nil end
    if pos.Y > 2200 or math.abs(pos.Y - 85000) < 8000 then return false, nil end
    local hardFloor = (OriginalFPDH and (OriginalFPDH - 25)) or -600
    if pos.Y <= math.min(hardFloor, -105) then return false, nil end
    local okV, vel = pcall(function() return p.AssemblyLinearVelocity end)
    if okV and vel and vel.Magnitude > 500 then return false, nil end
    local okAV, avel = pcall(function() return p.AssemblyAngularVelocity end)
    if okAV and avel and avel.Magnitude > 250 then return false, nil end
    return true, pos
end

isValidTargetWorldCF = function(cf)
    if not cf then return false end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return false end
    if pos.Magnitude < 0.5 or pos.Magnitude > 45000 then return false end
    if pos.Y > 2200 or math.abs(pos.Y - 85000) < 8000 then return false end
    local hardFloor = (OriginalFPDH and (OriginalFPDH - 25)) or -600
    if pos.Y <= math.min(hardFloor, -105) then return false end
    if isLethalVoidCF and isLethalVoidCF(cf) then return false end
    return true
end

isLocalCharAliveOrReanimated = function(char, hum)
    char = char or (LP and LP.Character)
    if not (char and char.Parent) then return false end
    hum = hum or char:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 then return true end
    if (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
        return true
    end
    if isCharacterNetlessReanimated and isCharacterNetlessReanimated(char) then
        return true
    end
    return false
end

isRefPartValid = function(part, char)
    local okBounds, pos = isPartInSafeWorldBounds(part)
    if not okBounds or not pos then return false end
    if char and not part:IsDescendantOf(char) then return false end

    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        local upper = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
        local head = char:FindFirstChild("Head")
        local okUpper, upperPos = isPartInSafeWorldBounds(upper)
        local okHead, headPos = isPartInSafeWorldBounds(head)

        -- 1. Desynced HumanoidRootPart / LowerTorso rejection (FE Invisibility, Seat-Invis, Waist-Break & Netless Reanim)
        if part.Name == "HumanoidRootPart" or part.Name == "LowerTorso" then
            -- During Permanent Death Reanimation (Health <= 0), never trust HumanoidRootPart if Torso/UpperTorso/Head is valid!
            if part.Name == "HumanoidRootPart" and hum and hum.Health <= 0 and (okUpper or okHead) then
                return false
            end
            if okUpper and (pos - upperPos).Magnitude > 4.5 then
                return false -- Root/LowerTorso is desynced from UpperTorso/Torso!
            end
            if okHead and (pos - headPos).Magnitude > 6.0 then
                return false -- Root/LowerTorso is desynced from Head!
            end
            -- Check if RootJoint / Root Motor6D was broken or disabled by FE Invisibility
            if part.Name == "HumanoidRootPart" and (okUpper or okHead) then
                local refBodyPos = (okUpper and upperPos) or headPos
                local rootJoint = part:FindFirstChild("RootJoint") or part:FindFirstChild("Root")
                    or (upper and (upper:FindFirstChild("RootJoint") or upper:FindFirstChild("Root")))
                if rootJoint and rootJoint:IsA("Motor6D") and not rootJoint.Enabled and (pos - refBodyPos).Magnitude > 1.8 then
                    return false
                end
            end
        end

        -- 2. Fling-Torso rejection: some netless reanim scripts spin/fling Torso while Head remains at real position
        if (part.Name == "Torso" or part.Name == "UpperTorso") and okHead then
            if (pos - headPos).Magnitude > 7.0 then
                local okAV, avel = pcall(function() return part.AssemblyAngularVelocity end)
                local okV, vel = pcall(function() return part.AssemblyLinearVelocity end)
                if part.Transparency >= 0.9 or (okAV and avel and avel.Magnitude > 80) or (okV and vel and vel.Magnitude > 160) then
                    return false
                end
            end
        end
    end
    return true
end

isCharacterNetlessReanimated = function(char)
    if not (char and char.Parent) then return false end
    local cands = {
        char:FindFirstChild("UpperTorso"),
        char:FindFirstChild("Torso"),
        char:FindFirstChild("Head"),
        char:FindFirstChild("LowerTorso"),
        char.PrimaryPart,
    }
    for _, part in ipairs(cands) do
        if part and part:IsA("BasePart") and isRefPartValid(part, char) then
            return true
        end
    end
    return false
end

findTargetReanimModel = function(targetPlr)
    if not targetPlr then return nil end
    -- Local player reanimation / ghost lookup
    if targetPlr == LP then
        local zApi = _G._AngoorZenApi
        if zApi and type(zApi.is_reanimated) == "function" and zApi.is_reanimated() and type(zApi.get_clone) == "function" then
            local okCl, cl = pcall(zApi.get_clone)
            if okCl and cl and cl.Parent then return cl end
        end
        if moveState and moveState.Vanish and moveState.Vanish.selfActive and moveState.Vanish.ghostModel and moveState.Vanish.ghostModel.Parent then
            return moveState.Vanish.ghostModel
        end
    end

    local tName = targetPlr.Name
    local tDisp = targetPlr.DisplayName or tName
    local candidates = {
        tName .. "_Fake",
        tName .. " Reanimation",
        tName .. "_Reanim",
        tName .. "Rig",
        tName .. "_Clone",
        tName .. " Dummy",
        tName .. "_Ghost",
        tDisp .. "_Fake",
        tDisp .. "_Clone",
        "CocoVanishGhost",
        "CocaReanimation",
        "AngoorReanimation",
    }
    local origChar = targetPlr.Character
    local function matchesTargetIdentity(m, ref)
        if not origChar then return true end
        local origBody = origChar:FindFirstChild("UpperTorso") or origChar:FindFirstChild("Torso") or origChar:FindFirstChild("Head")
        if origBody and origBody:IsA("BasePart") then
            local okB, bPos = isPartInSafeWorldBounds(origBody)
            if okB and bPos and (ref.Position - bPos).Magnitude < 40 then
                return true
            end
        end
        for _, acc in ipairs(origChar:GetChildren()) do
            if acc:IsA("Accessory") and m:FindFirstChild(acc.Name) then
                return true
            end
        end
        local origShirt = origChar:FindFirstChildOfClass("Shirt")
        local mShirt = m:FindFirstChildOfClass("Shirt")
        if origShirt and mShirt and origShirt.ShirtTemplate ~= "" and origShirt.ShirtTemplate == mShirt.ShirtTemplate then
            return true
        end
        return false
    end

    for _, cName in ipairs(candidates) do
        local m = workspace:FindFirstChild(cName) or (workspace.CurrentCamera and workspace.CurrentCamera:FindFirstChild(cName))
        if m and m:IsA("Model") and m ~= LP.Character then
            local ref = m:FindFirstChild("UpperTorso") or m:FindFirstChild("Torso") or m:FindFirstChild("Head") or m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
            if ref and ref:IsA("BasePart") and isRefPartValid(ref, m) then
                if cName == "CocaReanimation" or cName == "AngoorReanimation" or cName == "CocoVanishGhost" then
                    if matchesTargetIdentity(m, ref) then
                        return m
                    end
                else
                    return m
                end
            end
        end
    end

    local direct = workspace:FindFirstChild(tName)
    if direct and direct:IsA("Model") and direct ~= LP.Character and direct ~= targetPlr.Character then
        local ref = direct:FindFirstChild("UpperTorso") or direct:FindFirstChild("Torso") or direct:FindFirstChild("Head") or direct:FindFirstChild("HumanoidRootPart") or direct.PrimaryPart
        if ref and ref:IsA("BasePart") and isRefPartValid(ref, direct) then
            return direct
        end
    end

    for _, fName in ipairs({ "Characters", "Players", "Entities", "Live", "Units", "Ingame", "Chars" }) do
        local f = workspace:FindFirstChild(fName)
        local found = f and f:FindFirstChild(tName)
        if found and found:IsA("Model") and found ~= LP.Character and found ~= targetPlr.Character then
            local ref = found:FindFirstChild("UpperTorso") or found:FindFirstChild("Torso") or found:FindFirstChild("Head") or found:FindFirstChild("HumanoidRootPart") or found.PrimaryPart
            if ref and ref:IsA("BasePart") and isRefPartValid(ref, found) then
                return found
            end
        end
    end

    -- Fallback scan inside workspace.CurrentCamera or workspace for custom-named reanim/invis clones matching accessories/clothing
    if origChar then
        local origHum = origChar:FindFirstChildOfClass("Humanoid")
        local origHRP = origChar:FindFirstChild("HumanoidRootPart")
        local needsCloneScan = (origHum and origHum.Health <= 0) or (not origHRP) or (not isRefPartValid(origHRP, origChar))
        if needsCloneScan then
            local containers = { workspace.CurrentCamera, workspace }
            for _, cont in ipairs(containers) do
                if cont then
                    for _, child in ipairs(cont:GetChildren()) do
                        if child:IsA("Model") and child ~= LP.Character and child ~= origChar and not Players:GetPlayerFromCharacter(child) then
                            local ref = child:FindFirstChild("UpperTorso") or child:FindFirstChild("Torso") or child:FindFirstChild("Head")
                            if ref and ref:IsA("BasePart") and isRefPartValid(ref, child) and matchesTargetIdentity(child, ref) then
                                return child
                            end
                        end
                    end
                end
            end
        end
    end

    return nil
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- ⚡ ZERO-DELAY WELD & OMNIPRESENT TARGET CATCH-UP ENGINE (LINE-BY-LINE AUDITED)
--   • Eliminated PhysicsRepRootPart double-transform bug (which sent players to 2x
--     world coordinates / random places on the map when setting Root.CFrame)
--   • Uses upright root yaw (`getFlatYawCFrame`) + exact anatomical anchor points
--     so head-nods or torso tilts during animations never swing your character away
--   • Eliminated stale `WorldPivot` false-nearest trap so Auto-Nearest ALWAYS locks
--     onto real streamed-in players near you, while unstreamed targets are swept
--     and caught up to anywhere on the map!
-- ═══════════════════════════════════════════════════════════════════════════════
local computeDynamicHeightWeld = function() return 0, 1.0, 1.0 end

-- Sever any workspace SeatWeld / VehicleSeat weld or foreign joint holding our character before teleporting/welding
local function breakAllSeatsAndExternalJoints(char, hum, root)
    if not char then return end
    hum = hum or char:FindFirstChildOfClass("Humanoid")
    root = root or char:FindFirstChild("HumanoidRootPart")
    pcall(function()
        if hum then
            local seatPart = hum.SeatPart
            if seatPart and seatPart:IsA("BasePart") then
                pcall(function() seatPart.CanTouch = false end)
                for _, ch in ipairs(seatPart:GetChildren()) do
                    if ch:IsA("JointInstance") or ch:IsA("WeldConstraint") or ch.Name == "SeatWeld" then
                        pcall(function() ch:Destroy() end)
                    end
                end
                task.delay(0.45, function()
                    if seatPart and seatPart.Parent and not (Anti and Anti.SeatTrap and Anti.SeatTrap.enabled) then
                        pcall(function() seatPart.CanTouch = true end)
                    end
                end)
            end
            if hum.Sit then hum.Sit = false end
        end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                local okJ, joints = pcall(function() return part:GetJoints() end)
                if okJ and joints then
                    for _, j in ipairs(joints) do
                        if j:IsA("JointInstance") or j:IsA("WeldConstraint") then
                            local p0, p1 = j.Part0, j.Part1
                            local p0Mine = p0 and p0:IsDescendantOf(char)
                            local p1Mine = p1 and p1:IsDescendantOf(char)
                            if (p0Mine and p1 and not p1Mine) or (p1Mine and p0 and not p0Mine) or j.Name == "SeatWeld" then
                                pcall(function() j:Destroy() end)
                            end
                        end
                    end
                end
            elseif part:IsA("SeatWeld") or part.Name == "SeatWeld" then
                pcall(function() part:Destroy() end)
            end
        end
    end)
end

-- Build server sweep points (Spawns, Seats, VehicleSeats, Map Models) for catching up to unstreamed players
local getServerSweepPoints
do
local CachedSweepPoints = {}
local LastSweepBuildTick = 0
getServerSweepPoints = function()
    local now = tick()
    if #CachedSweepPoints > 0 and (now - LastSweepBuildTick) < 8.0 then
        return CachedSweepPoints
    end
    LastSweepBuildTick = now
    local pts = {}
    pcall(function()
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("SpawnLocation") or obj:IsA("Seat") or obj:IsA("VehicleSeat") then
                if not isLethalVoidCF(obj.CFrame) then
                    pts[#pts + 1] = obj.CFrame
                end
            end
        end
    end)
    for _, child in ipairs(workspace:GetChildren()) do
        if child:IsA("Model") and child ~= LP.Character and not Players:GetPlayerFromCharacter(child) then
            local okP, pCF = pcall(function() return child:GetPivot() end)
            if okP and pCF and pCF.Position.Magnitude > 10 and pCF.Position.Magnitude < 100000 and not isLethalVoidCF(pCF) then
                pts[#pts + 1] = pCF
            end
        elseif child:IsA("BasePart") and child.Position.Magnitude > 50 and child.Position.Magnitude < 100000 and not isLethalVoidCF(child.CFrame) then
            pts[#pts + 1] = child.CFrame
        end
    end
    CachedSweepPoints = pts
    return pts
end
end -- end getServerSweepPoints scope

local function WeldTo(TargetPart, Offset, Speaker, AnimationId, Osc, AnimFallbacks, TargetPlayer, RefMode, PreSeekSafeCF, PresetKey)
    local Character = Speaker.Character
    if not Character then return nil end
    local Root = Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChildWhichIsA("BasePart")
    local Humanoid = Character:FindFirstChildWhichIsA("Humanoid")
    if not Root or not Humanoid or not isLocalCharAliveOrReanimated(Character, Humanoid) then return nil end

    -- Stop Coca Reanim's standalone Bang lock if active so the two loops never fight over Root.CFrame
    if type(_G.stopCocaBangLock) == "function" then
        pcall(_G.stopCocaBangLock)
    end

    -- Cancel any pending void-return loop so it never fights our new weld connection (from khaman_dhokla.lua)
    RescueGeneration = RescueGeneration + 1
    Root.Anchored = false
    breakAllSeatsAndExternalJoints(Character, Humanoid, Root)

    local TargetChar = (TargetPart and TargetPart.Parent) or (TargetPlayer and findPlayerCharacterAnywhere(TargetPlayer))
    local TargetHum  = TargetChar and TargetChar:FindFirstChildOfClass("Humanoid")
    local lastSafeCF = (PreSeekSafeCF and typeof(PreSeekSafeCF) == "CFrame" and isSafePlayableCF(PreSeekSafeCF) and PreSeekSafeCF)
        or (isSafePlayableCF(LastKnownSafeCF) and LastKnownSafeCF)
        or (isSafePlayableCF(Root.CFrame) and Root.CFrame)
        or findFallbackSafeCF()
    local targetUid  = TargetPlayer and TargetPlayer.UserId or nil
    local targetName = TargetPlayer and TargetPlayer.Name or "Target"
    local targetDisp = (TargetPlayer and TargetPlayer.DisplayName) or targetName

    pcall(function() workspace.FallenPartsDestroyHeight = 0/0 end)
    pcall(function() Humanoid.Sit = false end)
    pcall(function() Humanoid.PlatformStand = true end)
    pcall(function() Humanoid.AutoRotate = false end)
    forcePhysicsState(Humanoid)
    killAnimate(Character)

    local AnimTrack, AnimInstance = nil, nil
    local animLoading = false
    local animAttempts = 0
    local Weld = { destroyed = false }

    local function ensureAnim(force)
        if not AnimationId or Weld.destroyed or animLoading then return end
        if AnimTrack and not force then
            local ip = false
            pcall(function()
                ip = AnimTrack.IsPlaying
                if ip and AnimTrack.Length > 0 and AnimTrack.TimePosition >= (AnimTrack.Length - 0.04) then
                    AnimTrack.TimePosition = 0
                end
            end)
            if ip then
                pcall(function() AnimTrack:AdjustSpeed(math.clamp(V.Speed or 1.0, 0.2, 6.0)) end)
                return
            end
        end
        animAttempts = animAttempts + 1
        if not force and animAttempts % 15 ~= 0 and AnimTrack then return end
        animLoading = true
        task.spawn(function()
            pcall(function()
                if Weld.destroyed or not Character.Parent then return end
                local Animator = Character:FindFirstChildWhichIsA("Animator", true)
                if not Animator and Humanoid then
                    Animator = Instance.new("Animator")
                    Animator.Parent = Humanoid
                end
                if not Animator then return end
                local track, anim = loadPlayableAnim(Animator, AnimationId, AnimFallbacks, Humanoid)
                if Weld.destroyed then
                    if track then pcall(function() track:Stop(0); track:Destroy() end) end
                    if anim then pcall(function() anim:Destroy() end) end
                    return
                end
                if track then
                    pcall(function()
                        track.Looped = true
                        track:AdjustSpeed(math.clamp(V.Speed or 1.0, 0.2, 6.0))
                    end)
                    if AnimTrack and AnimTrack ~= track then
                        pcall(function() AnimTrack:Stop(0); AnimTrack:Destroy() end)
                    end
                    if AnimInstance and AnimInstance ~= anim then
                        pcall(function() AnimInstance:Destroy() end)
                    end
                    AnimTrack = track
                    AnimInstance = anim
                end
            end)
            animLoading = false
        end)
    end
    -- Load animation asynchronously so Frame-0 CFrame lock is NEVER delayed!
    ensureAnim(true)

    local weldCachedParts = {}
    local WeldDescConn = nil
    if Character then
        for _, v in ipairs(Character:GetDescendants()) do
            if v:IsA("BasePart") then
                weldCachedParts[#weldCachedParts + 1] = v
            elseif v:IsA("SeatWeld") or v.Name == "SeatWeld" then
                pcall(function() v:Destroy() end)
            end
        end
        WeldDescConn = Character.DescendantAdded:Connect(function(v)
            if Weld.destroyed then return end
            if v:IsA("BasePart") then
                weldCachedParts[#weldCachedParts + 1] = v
                v.CanCollide = false
                v.CanTouch = false
                v.CanQuery = false
                v.Massless = true
                v.Anchored = false
            elseif v:IsA("Tool") then
                for _, tp in ipairs(v:GetDescendants()) do
                    if tp:IsA("BasePart") then
                        weldCachedParts[#weldCachedParts + 1] = tp
                        tp.CanCollide = false
                        tp.CanTouch = false
                        tp.CanQuery = false
                        tp.Massless = true
                        tp.Anchored = false
                    end
                end
            elseif v:IsA("SeatWeld") or v.Name == "SeatWeld" then
                pcall(function() v:Destroy() end)
            end
        end)
    end

    local function applyPhaseNoclip()
        if not Character or not Character.Parent then return end
        for i = 1, #weldCachedParts do
            local v = weldCachedParts[i]
            if v and v.Parent then
                if v.CanCollide then v.CanCollide = false end
                if v.CanTouch then v.CanTouch = false end
                if v.CanQuery then v.CanQuery = false end
                if not v.Massless then v.Massless = true end
                if v.Anchored then v.Anchored = false end
            end
        end
        if Humanoid and Humanoid.Sit then
            pcall(function() Humanoid.Sit = false end)
        end
    end
    applyPhaseNoclip()

    local Conn = nil
    local RenderConn = nil
    local StepConn = nil
    local clock = 0
    local missingFrames = 0
    local lastStreamReq = 0
    local currentLockCF = nil

    local function syncReanimRoots(attachCF)
        local zApi = _G._AngoorZenApi
        if zApi and type(zApi.is_reanimated) == "function" and type(zApi.get_real_character) == "function" then
            local okR, isReanim = pcall(zApi.is_reanimated)
            if okR and isReanim then
                local okC, realChar = pcall(zApi.get_real_character)
                local realRoot = okC and realChar and realChar:FindFirstChild("HumanoidRootPart")
                if realRoot and realRoot ~= Root and realRoot.Parent then
                    realRoot.Anchored = false
                    realRoot.CFrame = attachCF
                    realRoot.AssemblyLinearVelocity = Vector3.zero
                    realRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end
        local skyApi = _G.CocaSkyDestroyer
        if skyApi and type(skyApi.is_reanimated) == "function" and type(skyApi.get_real_character) == "function" then
            local okS, isSkyReanim = pcall(skyApi.is_reanimated)
            if okS and isSkyReanim then
                local okSC, skyRealChar = pcall(skyApi.get_real_character)
                local skyRealRoot = okSC and skyRealChar and skyRealChar:FindFirstChild("HumanoidRootPart")
                if skyRealRoot and skyRealRoot ~= Root and skyRealRoot.Parent then
                    skyRealRoot.Anchored = false
                    skyRealRoot.CFrame = attachCF
                    skyRealRoot.AssemblyLinearVelocity = Vector3.zero
                    skyRealRoot.AssemblyAngularVelocity = Vector3.zero
                end
            end
        end
    end

    function Weld:Destroy(skipReturn)
        if self.destroyed then return end
        self.destroyed = true
        pcall(function() RunService:UnbindFromRenderStep("CocoWeldZeroDelayPreCam") end)
        pcall(function() RunService:UnbindFromRenderStep("CocoWeldZeroDelayLock") end)
        if WeldDescConn then WeldDescConn:Disconnect(); WeldDescConn = nil end
        if Conn then Conn:Disconnect(); Conn = nil end
        if RenderConn then RenderConn:Disconnect(); RenderConn = nil end
        if StepConn then StepConn:Disconnect(); StepConn = nil end
        pcall(function() LP.ReplicationFocus = nil end)
        if Root and sethiddenproperty then
            pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
        end
        if AnimTrack then
            pcall(function() AnimTrack:Stop(0) end)
            pcall(function() AnimTrack:Destroy() end)
            AnimTrack = nil
        end
        if AnimInstance then
            pcall(function() AnimInstance:Destroy() end)
            AnimInstance = nil
        end
        if CurrentWeld == self then
            CurrentWeld = nil
        end
        if not skipReturn then
            LastVoidActionEnd = tick()
            safeReturnFromVoid(Character, lastSafeCF)
            if LP.Character and LP.Character ~= Character then
                safeReturnFromVoid(LP.Character, lastSafeCF)
            end
        end
    end

    local lastValidTargetPos = (TargetPart and isRefPartValid(TargetPart, TargetChar)) and TargetPart.Position or nil
    local lastValidLockCF = nil

    local function isSuspiciousInvisOrReanimJump(part, char, prevPos)
        if not (part and part.Parent) then return true end
        if not isRefPartValid(part, char) then return true end
        local pos = part.Position
        if prevPos then
            local jumpDist = (pos - prevPos).Magnitude
            if jumpDist > 165 then
                -- Check if another body part (Torso/UpperTorso/Head) or reanim clone stayed near prevPos!
                if char then
                    for _, bName in ipairs({ "UpperTorso", "Torso", "Head" }) do
                        local bp = char:FindFirstChild(bName)
                        if bp and bp ~= part and bp:IsA("BasePart") and isRefPartValid(bp, char) then
                            if (bp.Position - prevPos).Magnitude < 65 then
                                return true -- Current part jumped away while real body stayed!
                            end
                        end
                    end
                end
                local rModel = TargetPlayer and findTargetReanimModel(TargetPlayer)
                if rModel and rModel ~= char then
                    return true
                end
                -- Reject jumps into sky/underground/void pockets or invisible dump boxes
                if pos.Y > 850 or pos.Y < -60 or pos.Magnitude > 14000 then
                    return true
                end
                local head = char and char:FindFirstChild("Head")
                local torso = char and (char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
                if (head and head:IsA("BasePart") and head.Transparency >= 0.95)
                    and (torso and torso:IsA("BasePart") and torso.Transparency >= 0.95) then
                    return true -- Target's real rig just turned invisible & teleported to a dump spot!
                end
            end
        end
        return false
    end

    local function updateZeroDelayLockCF()
        if Weld.destroyed then return end
        if Root and Root.Parent then
            -- Dynamically verify that TargetPart has not desynced, voided, or jumped to sky/invis dump (FE Invis / Reanim)
            if isSuspiciousInvisOrReanimJump(TargetPart, TargetChar, lastValidTargetPos) then
                local resolvedChar = (TargetPlayer and findPlayerCharacterAnywhere(TargetPlayer)) or TargetChar
                if resolvedChar and resolvedChar ~= TargetChar then
                    TargetChar = resolvedChar
                    TargetHum  = resolvedChar:FindFirstChildOfClass("Humanoid")
                end
                local newPart = TargetChar and pickTargetRef(TargetChar, RefMode or "torso")
                if newPart and not isSuspiciousInvisOrReanimJump(newPart, TargetChar, lastValidTargetPos) then
                    TargetPart = newPart
                else
                    -- Target is mid-invisibility/reanim dump transition: clear ReplicationFocus/PhysicsRepRootPart and hold safe lock position!
                    pcall(function() LP.ReplicationFocus = nil end)
                    if sethiddenproperty then
                        pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
                        pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
                    end
                    if lastValidLockCF then
                        currentLockCF = lastValidLockCF
                        Root.CFrame = lastValidLockCF
                        Root.AssemblyLinearVelocity = Vector3.zero
                        Root.AssemblyAngularVelocity = Vector3.zero
                        syncReanimRoots(lastValidLockCF)
                    end
                    return
                end
            end

            if TargetPart and TargetPart.Parent and isRefPartValid(TargetPart, TargetChar) then
                lastValidTargetPos = TargetPart.Position
                local customAdjust = CFrame.new(V.X or 0, V.Y or 0, (V.Z or 1.3) - 1.3)
                local localOffset = Offset * customAdjust
                if Osc and Osc.period and Osc.period > 0 then
                    local phase = (math.sin(clock * (2 * math.pi) / Osc.period) + 1) * 0.5
                    localOffset = localOffset * CFrame.new(0, 0, -Osc.distance * phase)
                end
                currentLockCF = TargetPart.CFrame * localOffset
                lastValidLockCF = currentLockCF
                Root.CFrame = currentLockCF
                syncReanimRoots(currentLockCF)
            end
        end
    end

    -- Immediate Frame-0 Lock + Zero-Delay Network Replication Bind (0.00ms startup delay!)
    -- Always bind PhysicsRepRootPart & ReplicationFocus to the validated TargetPart (NEVER an unvalidated desynced HumanoidRootPart!)
    if TargetPart and TargetPart.Parent and Root and Root.Parent and isRefPartValid(TargetPart, TargetChar) then
        local focusInit = TargetPart
        pcall(function() LP.ReplicationFocus = focusInit end)
        if sethiddenproperty then
            pcall(function()
                sethiddenproperty(Root, "PhysicsRepRootPart", focusInit)
                if InstanceHandleNew then
                    sethiddenproperty(Root, "PhysicsRepRootRef", InstanceHandleNew(focusInit))
                end
                sethiddenproperty(Root, "NetworkIsSleeping", false)
            end)
        end
        updateZeroDelayLockCF()
    end

    pcall(function()
        RunService:BindToRenderStep("CocoWeldZeroDelayPreCam", Enum.RenderPriority.Camera.Value - 1, updateZeroDelayLockCF)
        RunService:BindToRenderStep("CocoWeldZeroDelayLock", Enum.RenderPriority.Character.Value + 1, updateZeroDelayLockCF)
    end)

    -- Stepped pass ensures we phase through walls, doors, roofs, and seats inside any hiding spot
    StepConn = RunService.Stepped:Connect(function()
        if Weld.destroyed then return end
        applyPhaseNoclip()
        updateZeroDelayLockCF()
    end)

    -- RenderStepped pass guarantees zero-jitter visual lock when the target sprints or turns camera (exact khaman_dhokla.lua math)
    RenderConn = RunService.RenderStepped:Connect(function()
        if Weld.destroyed then return end
        updateZeroDelayLockCF()
    end)

    Conn = RunService.Heartbeat:Connect(function(dt)
        -- 1. Check if our own character died or respawned
        if not Character.Parent or Character ~= LP.Character or not Root.Parent or not Humanoid.Parent or not isLocalCharAliveOrReanimated(Character, Humanoid) then
            Weld:Destroy(true)
            return
        end

        -- 2. Check if target player left the server completely
        if TargetPlayer and TargetPlayer.Parent ~= Players then
            local savedKey = PresetKey or WeldIntent.presetKey or LastPresetKey or "facebang"
            WeldIntent.leftInfo = {
                userId = targetUid,
                name = targetName,
                displayName = targetDisp,
                accountAge = "—",
                friendsText = "—",
                leftAt = tick(),
                wasWelded = true,
                presetKey = savedKey,
            }
            WeldIntent.active = false
            WeldIntent.target = nil
            WeldIntent.waitingForSpawn = true
            WeldIntent.topStatusText = "target left · weld stopped"
            WeldIntent.topStatusColor = T.Danger
            WeldIntent.midStatusText = "target left · " .. targetName
            WeldIntent.midStatusColor = T.Danger
            WeldIntent.bottomStatusText = "target offline · will attach on spawn"
            WeldIntent.bottomStatusColor = T.Warning
            Weld:Destroy(false)
            if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
            if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
            showOwnerScreenBanner(
                "🚨 TARGET HAS LEFT THE GAME",
                "@" .. targetName .. " (" .. targetDisp .. ") left — weld stopped · will attach on spawn",
                T.Danger,
                4.5,
                "TargetLeftBanner"
            )
            notify("COCO POWDER", "Target left server — safely returned")
            return
        end

        -- 3. Check if target died or reanimated (Zero-Delay Reanimation & Invisibility Protection)
        if TargetHum and TargetHum.Parent and TargetHum.Health <= 0 then
            local isReanimActive = false
            local reanimChar = TargetPlayer and findTargetReanimModel(TargetPlayer)
            if reanimChar and reanimChar ~= TargetChar then
                TargetChar = reanimChar
                TargetHum  = reanimChar:FindFirstChildOfClass("Humanoid")
                TargetPart = pickTargetRef(reanimChar, RefMode or "torso")
                missingFrames = 0
                isReanimActive = true
            elseif TargetChar and isCharacterNetlessReanimated(TargetChar) then
                local validPart = pickTargetRef(TargetChar, RefMode or "torso")
                if validPart and validPart.Parent and isRefPartValid(validPart, TargetChar) then
                    TargetPart = validPart
                    missingFrames = 0
                    isReanimActive = true
                end
            end

            if not isReanimActive then
                WeldIntent.waitingForSpawn = true
                WeldIntent.topStatusText = "target respawning · waiting"
                WeldIntent.topStatusColor = T.Warning
                WeldIntent.midStatusText = "respawning · " .. targetName
                WeldIntent.midStatusColor = T.Warning
                WeldIntent.bottomStatusText = "target respawning · will attach on spawn"
                WeldIntent.bottomStatusColor = T.Warning
                if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
                Weld:Destroy(false)
                return
            end
        end

        -- 4. OMNIPRESENT RE-LOCK: If TargetPart streamed out, desynced from invis/reanim, or switched character model
        if not TargetPart or not TargetPart.Parent or not isRefPartValid(TargetPart, TargetChar) or (TargetPlayer and findPlayerCharacterAnywhere(TargetPlayer) ~= TargetChar) then
            if TargetPlayer then
                local newChar = findPlayerCharacterAnywhere(TargetPlayer)
                local newHum  = newChar and newChar:FindFirstChildOfClass("Humanoid")
                local isReanim = (newChar and isCharacterNetlessReanimated(newChar)) or (findTargetReanimModel(TargetPlayer) ~= nil)
                if newHum and newHum.Health <= 0 and not isReanim then
                    WeldIntent.waitingForSpawn = true
                    Weld:Destroy(false)
                    return
                end
                local newPart = newChar and pickTargetRef(newChar, RefMode or "torso")
                if newPart and newPart.Parent and not isSuspiciousInvisOrReanimJump(newPart, newChar, lastValidTargetPos) then
                    TargetChar = newChar
                    TargetHum  = newHum
                    TargetPart = newPart
                    missingFrames = 0
                else
                    missingFrames = missingFrames + 1
                    pcall(function() LP.ReplicationFocus = nil end)
                    if sethiddenproperty then
                        pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
                        pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
                    end
                    -- Distinguish truly unstreamed character (0 BaseParts in workspace) from FE Invisibility / Reanim dump (BaseParts exist but are in invalid sky/void/dump coords)!
                    local hasStreamedParts = (newChar and newChar:FindFirstChildWhichIsA("BasePart", true) ~= nil)
                    if hasStreamedParts then
                        -- Target's character IS in workspace, just mid-invisibility or reanimation transition! Hold safe position in place so we NEVER teleport to another place!
                        local holdCF = lastValidLockCF or currentLockCF or lastSafeCF
                        if holdCF then
                            Root.CFrame = holdCF
                            Root.AssemblyLinearVelocity = Vector3.zero
                            Root.AssemblyAngularVelocity = Vector3.zero
                            syncReanimRoots(holdCF)
                        end
                    else
                        -- Target is genuinely unstreamed; only follow if hiddenCF is a verified, non-dump world coordinate
                        local hiddenCF = getBestTargetCFrame(TargetPlayer)
                        if hiddenCF and isValidTargetWorldCF(hiddenCF) then
                            local now = tick()
                            if now - lastStreamReq > 0.35 then
                                lastStreamReq = now
                                task.spawn(function()
                                    pcall(function() LP:RequestStreamAroundAsync(hiddenCF.Position, 1) end)
                                end)
                            end
                            Root.CFrame = hiddenCF * Offset
                            Root.AssemblyLinearVelocity = Vector3.zero
                            Root.AssemblyAngularVelocity = Vector3.zero
                            markIntentionalTeleport(Root.CFrame)
                        end
                    end
                    if missingFrames > 180 then
                        Weld:Destroy(false)
                    end
                    return
                end
            else
                Weld:Destroy(false)
                return
            end
        else
            missingFrames = 0
        end

        -- 5. VOID PROTECTION: Only detach if the target is genuinely plummeting in the lethal void killzone
        local tVel = TargetPart.AssemblyLinearVelocity
        if isLethalVoidCF(TargetPart.CFrame, tVel) then
            local altPart = TargetChar and (TargetChar:FindFirstChild("UpperTorso") or TargetChar:FindFirstChild("Torso") or TargetChar:FindFirstChild("Head"))
            if altPart and altPart ~= TargetPart and isRefPartValid(altPart, TargetChar) and not isLethalVoidCF(altPart.CFrame, altPart.AssemblyLinearVelocity) then
                TargetPart = altPart
            else
                Weld:Destroy(false)
                notify("COCO POWDER", "Target fell into lethal Void — detached safely!")
                return
            end
        end

        -- Keep server streaming & PhysicsRepRootPart focused strictly on the validated TargetPart (NEVER an unvalidated desynced HumanoidRootPart!)
        local focusPart = TargetPart
        pcall(function() LP.ReplicationFocus = focusPart end)

        -- Cache target location & update safe standing CFrame only when target is near stable ground
        if TargetPlayer then
            PlayerLocationCache[TargetPlayer.UserId] = { cf = TargetPart.CFrame, time = tick(), verified = true }
            WeldIntent.waitingForSpawn = false
        end
        if not isLethalVoidCF(TargetPart.CFrame, tVel) and math.abs(tVel.Y) < 45 and (not TargetHum or TargetHum.FloorMaterial ~= Enum.Material.Air) then
            local _, yYaw, _ = TargetPart.CFrame:ToEulerAnglesYXZ()
            lastSafeCF = CFrame.new(TargetPart.Position + Vector3.new(0, 2.5, 0)) * CFrame.Angles(0, yYaw, 0)
            LastKnownSafeCF = lastSafeCF
        end

        local animate = Character:FindFirstChild("Animate")
        if animate and not animate.Disabled then
            animate.Disabled = true
            AnimateWasDisabled = true
        end

        local speedMult = math.clamp(V.Speed or 1.0, 0.2, 6.0)
        clock = clock + (dt * speedMult)
        local customAdjust = CFrame.new(V.X or 0, V.Y or 0, (V.Z or 1.3) - 1.3)
        local localOffset = Offset * customAdjust
        if Osc and Osc.period and Osc.period > 0 then
            local phase = (math.sin(clock * (2 * math.pi) / Osc.period) + 1) * 0.5
            localOffset = localOffset * CFrame.new(0, 0, -Osc.distance * phase)
        end
        currentLockCF = TargetPart.CFrame * localOffset
        Root.CFrame = currentLockCF
        syncReanimRoots(currentLockCF)
        -- Velocity-matched anti-sleep replication (from khaman_dhokla.lua): prevents network sleep & trailing lag on other players' screens
        local microWake = Vector3.new(0, math.sin(clock * 24) * 0.03, 0)
        Root.AssemblyLinearVelocity = (tVel.Magnitude < 350 and (tVel * 0.85) or Vector3.zero) + microWake
        Root.AssemblyAngularVelocity = Vector3.zero
        markIntentionalTeleport(Root.CFrame)
        if sethiddenproperty then pcall(function()
            sethiddenproperty(Root, "PhysicsRepRootPart", focusPart)
            if InstanceHandleNew then
                sethiddenproperty(Root, "PhysicsRepRootRef", InstanceHandleNew(focusPart))
            end
            sethiddenproperty(Root, "NetworkIsSleeping", false)
        end) end
        pcall(function() ensureAnim(false) end)
        pcall(function()
            if not Humanoid.PlatformStand then Humanoid.PlatformStand = true end
            if Humanoid.Sit then Humanoid.Sit = false end
        end)
    end)

    return Weld
end

local function unweld(skipReturn)
    if CurrentWeld then
        pcall(function() CurrentWeld:Destroy(skipReturn) end)
        CurrentWeld = nil
    end
    if not skipReturn and LP.Character then
        pcall(function() safeReturnFromVoid(LP.Character, LastKnownSafeCF) end)
    end
    if not (Anti and Anti.Void and Anti.Void.enabled) and not (Anti and Anti.Kill and Anti.Kill.enabled) then
        pcall(function() workspace.FallenPartsDestroyHeight = OriginalFPDH end)
    end
end

