-- Compute a clean, level, upright CFrame relative to a target part/character
getFlatYawCFrame = function(cf, posOverride)
    if not cf then return CFrame.new() end
    local pos = posOverride or cf.Position
    local look = cf.LookVector
    local flatLook = Vector3.new(look.X, 0, look.Z)
    if flatLook.Magnitude > 0.001 then
        return CFrame.lookAt(pos, pos + flatLook.Unit, Vector3.yAxis)
    end
    local _, yYaw, _ = cf:ToEulerAnglesYXZ()
    return CFrame.new(pos) * CFrame.Angles(0, yYaw, 0)
end

-- Cached character lookup to avoid expensive recursive Workspace scans every frame (from khaman_dhokla.lua)
do
local CustomCharLookupCache = {} -- [userId] = { model = Instance, lastScan = number }
local CommonCharContainers = { "Characters", "Players", "Entities", "Live", "Units", "Ingame", "Chars" }
local LastGlobalDeepCharScan = 0
local TargetRefCache = setmetatable({}, { __mode = "k" })

findPlayerCharacterAnywhere = function(plr, skipDeepSearch)
    if not plr then return nil end
    -- Check for live reanimated clone or ghost avatar first (0.00ms Zero-Delay)
    local reanimModel = findTargetReanimModel(plr)
    if reanimModel and reanimModel.Parent then
        CustomCharLookupCache[plr.UserId] = { model = reanimModel, lastScan = tick() }
        return reanimModel
    end

    if plr.Character and plr.Character.Parent then
        CustomCharLookupCache[plr.UserId] = { model = plr.Character, lastScan = tick() }
        return plr.Character
    end
    local cached = CustomCharLookupCache[plr.UserId]
    if cached and cached.model and cached.model.Parent then
        return cached.model
    end
    -- Fast top-level & common character container check (O(1), zero lag)
    local direct = workspace:FindFirstChild(plr.Name)
    if direct and direct:IsA("Model") and direct ~= LP.Character then
        CustomCharLookupCache[plr.UserId] = { model = direct, lastScan = tick() }
        return direct
    end
    for _, folderName in ipairs(CommonCharContainers) do
        local folder = workspace:FindFirstChild(folderName)
        local found = folder and folder:FindFirstChild(plr.Name)
        if found and found:IsA("Model") and found ~= LP.Character then
            CustomCharLookupCache[plr.UserId] = { model = found, lastScan = tick() }
            return found
        end
    end
    -- Globally throttled deep search: prevents multi-player recursive workspace scans from ever spiking FPS
    if not skipDeepSearch then
        local now = tick()
        if (now - LastGlobalDeepCharScan) > 2.5 and (not cached or (now - (cached.lastScan or 0)) > 6.0) then
            LastGlobalDeepCharScan = now
            CustomCharLookupCache[plr.UserId] = { model = nil, lastScan = now }
            local byName = workspace:FindFirstChild(plr.Name, true)
            if byName and byName:IsA("Model") and byName ~= LP.Character and (byName:FindFirstChildOfClass("Humanoid") or byName.PrimaryPart or byName:FindFirstChildWhichIsA("BasePart", true)) then
                CustomCharLookupCache[plr.UserId] = { model = byName, lastScan = now }
                return byName
            end
        end
    end
    return plr.Character
end

-- Deep fallback reference part resolver with weak-table caching & instant FE Invis/Reanim root-desync immunity
pickTargetRef = function(char, mode)
    if not char then return nil end
    local cacheKey = (mode == "head") and "head" or ((mode == "root") and "root" or "torso")
    local hum = char:FindFirstChildOfClass("Humanoid")
    local isDeadOrReanim = (hum and hum.Health <= 0)
    local cEntry = TargetRefCache[char]
    if cEntry and cEntry[cacheKey] then
        local cachedPart = cEntry[cacheKey]
        if isRefPartValid(cachedPart, char) and not (isDeadOrReanim and cachedPart.Name == "HumanoidRootPart") then
            return cachedPart
        else
            cEntry[cacheKey] = nil
        end
    end
    local resolved = nil
    if mode == "head" then
        local h = char:FindFirstChild("Head") or char:FindFirstChild("head", true)
        if h and h:IsA("BasePart") and isRefPartValid(h, char) then
            resolved = h
        else
            for _, desc in ipairs(char:GetDescendants()) do
                if desc:IsA("BasePart") and desc.Name:lower():find("head", 1, true) and isRefPartValid(desc, char) then
                    resolved = desc
                    break
                end
            end
        end
    end
    if not resolved then
        local hrp = char:FindFirstChild("HumanoidRootPart") or (hum and hum.RootPart)
        local torso = char:FindFirstChild("Torso")
        local upperTorso = char:FindFirstChild("UpperTorso")
        local lowerTorso = char:FindFirstChild("LowerTorso")
        local head = char:FindFirstChild("Head")

        local bodyAnchor = (torso and torso:IsA("BasePart") and isRefPartValid(torso, char) and torso)
            or (upperTorso and upperTorso:IsA("BasePart") and isRefPartValid(upperTorso, char) and upperTorso)

        -- Only use HumanoidRootPart if it is valid, character is not in 0-HP reanim state, and HRP is tightly aligned with Torso/UpperTorso
        local hrpValid = (hrp and hrp:IsA("BasePart") and not isDeadOrReanim and isRefPartValid(hrp, char))
        if hrpValid and bodyAnchor and (hrp.Position - bodyAnchor.Position).Magnitude > 3.2 then
            hrpValid = false
        end

        if hrpValid then
            resolved = hrp
        elseif bodyAnchor then
            resolved = bodyAnchor
        elseif head and head:IsA("BasePart") and isRefPartValid(head, char) then
            resolved = head
        elseif lowerTorso and lowerTorso:IsA("BasePart") and isRefPartValid(lowerTorso, char) then
            resolved = lowerTorso
        elseif char.PrimaryPart and char.PrimaryPart.Name ~= "HumanoidRootPart" and isRefPartValid(char.PrimaryPart, char) then
            resolved = char.PrimaryPart
        elseif hum and hum.SeatPart and hum.SeatPart:IsA("BasePart") and isRefPartValid(hum.SeatPart, char) then
            resolved = hum.SeatPart
        else
            for _, desc in ipairs(char:GetDescendants()) do
                if desc:IsA("BasePart") and desc.Name ~= "HumanoidRootPart" and isRefPartValid(desc, char) then
                    resolved = desc
                    break
                end
            end
        end
    end
    if resolved then
        if not cEntry then
            cEntry = {}
            TargetRefCache[char] = cEntry
        end
        cEntry[cacheKey] = resolved
    end
    return resolved
end
end

local function getVerifiedStreamedCFrame(plr)
    if not plr then return nil end
    local char = findPlayerCharacterAnywhere(plr)
    if char and char.Parent then
        local part = pickTargetRef(char, "torso")
        if part and part.Parent and isRefPartValid(part, char) then
            local cf = part.CFrame
            if isValidTargetWorldCF(cf) then
                PlayerLocationCache[plr.UserId] = { cf = cf, time = tick(), verified = true }
                return cf
            end
        end
    end
    return nil
end

-- Resolve a player's CFrame even when their Character's BaseParts are 100% streamed out by StreamingEnabled!
-- NEVER falls back to GetPivot()/WorldPivot when the character already has streamed BaseParts (prevents FE Invisibility / Reanim sky/void RootPart from poisoning cache!)
getBestTargetCFrame = function(plr, skipDeepSearch)
    if not plr then return nil end
    local char = findPlayerCharacterAnywhere(plr, skipDeepSearch)
    if char then
        local part = pickTargetRef(char, "torso")
        if part and part.Parent and isRefPartValid(part, char) then
            local cf = part.CFrame
            if isValidTargetWorldCF(cf) then
                PlayerLocationCache[plr.UserId] = { cf = cf, time = tick(), verified = true }
                return cf
            end
        end
        -- Only consult Model:GetPivot() / WorldPivot when StreamingEnabled has culled ALL BaseParts from char!
        local hasAnyStreamedPart = (char:FindFirstChildWhichIsA("BasePart", true) ~= nil)
        if not hasAnyStreamedPart then
            local okPivot, pivotCF = pcall(function() return char:GetPivot() end)
            if okPivot and pivotCF and isValidTargetWorldCF(pivotCF) then
                PlayerLocationCache[plr.UserId] = { cf = pivotCF, time = tick() }
                return pivotCF
            end
            local okWP, wpCF = pcall(function() return char.WorldPivot end)
            if okWP and wpCF and isValidTargetWorldCF(wpCF) then
                PlayerLocationCache[plr.UserId] = { cf = wpCF, time = tick() }
                return wpCF
            end
        end
    end
    local cached = PlayerLocationCache[plr.UserId]
    if cached and cached.cf and isValidTargetWorldCF(cached.cf) then
        return cached.cf
    end
    return nil
end

local function getTargetStreamHintCFrame(plr)
    return getBestTargetCFrame(plr)
end

local function ensureStreamFocusAt(cfOrPos)
    local pos = nil
    if typeof(cfOrPos) == "CFrame" then
        pos = cfOrPos.Position
    elseif typeof(cfOrPos) == "Vector3" then
        pos = cfOrPos
    end
    if not pos then return end
    task.spawn(function()
        pcall(function() LP:RequestStreamAroundAsync(pos, 1) end)
    end)
end

-- Throttled background scanner (2.5Hz, non-recursive) that caches every player's position & pivot without frame lag
do
    local lastScanTick = 0
    RunService.Heartbeat:Connect(function()
        local now = os.clock()
        if now - lastScanTick < 0.40 then return end
        lastScanTick = now
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP then
                pcall(function() getBestTargetCFrame(p, true) end)
            end
        end
    end)
end

-- Active Stream-Piercer & Server Hiding-Spot Seeker (from khaman_dhokla.lua):
-- Instant return when target is already streamed; throttled async stream requests when unstreamed.
streamAndTeleportToTarget = function(targetPlr, refMode, maxWaitSeconds, allowSweepOrOffset)
    if not targetPlr or targetPlr.Parent ~= Players then return nil, nil end
    maxWaitSeconds = maxWaitSeconds or 1.8
    local allowSweep = (allowSweepOrOffset == true)
    local stepOffset = (typeof(allowSweepOrOffset) == "CFrame") and allowSweepOrOffset or CFrame.new(0, 1.5, 2)
    local myChar = LP.Character
    local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
    local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
    local originSafeCF = (myRoot and isSafePlayableCF(myRoot.CFrame) and myRoot.CFrame) or LastKnownSafeCF or findFallbackSafeCF()

    local function snapToFoundRef(charObj, refPart)
        myChar = LP.Character
        myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
        if myChar and myRoot then
            if sethiddenproperty then
                pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", nil) end)
                pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootRef", nil) end)
            end
            breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
            if myHum and myHum.Sit then pcall(function() myHum.Sit = false end) end
            myRoot.Anchored = false
            local destCF = refPart.CFrame * stepOffset
            markIntentionalTeleport(destCF)
            myRoot.AssemblyLinearVelocity = Vector3.zero
            myRoot.AssemblyAngularVelocity = Vector3.zero
            myRoot.CFrame = destCF
        end
        return charObj, refPart
    end

    -- Fast path: if target's reference part is already streamed in, connect immediately in 0.00ms!
    local tChar = findPlayerCharacterAnywhere(targetPlr)
    local tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
    local isTReanim = (tChar and isCharacterNetlessReanimated(tChar)) or (findTargetReanimModel(targetPlr) ~= nil)
    if (tHum and tHum.Health <= 0) and not isTReanim then
        return tChar, nil
    end
    local tRef = tChar and pickTargetRef(tChar, refMode or "torso")
    if tRef and tRef.Parent and not isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
        return snapToFoundRef(tChar, tRef)
    end

    -- Target is in an unstreamed chunk. Guard with WeldSeekingTarget so Anti-Void / Anti-Bring never yank us back mid-stream!
    local prevSeeking = WeldSeekingTarget
    WeldSeekingTarget = true
    local didTeleportFromOrigin = false

    if myChar then
        breakAllSeatsAndExternalJoints(myChar, myHum, myRoot)
        if myHum and myHum.Sit then pcall(function() myHum.Sit = false end) end
    end

    local started = tick()
    local lastStreamCall = 0
    while tick() - started < (maxWaitSeconds * 0.75) do
        if targetPlr.Parent ~= Players then break end
        tChar = findPlayerCharacterAnywhere(targetPlr)
        tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
        local isLoopReanim = (tChar and isCharacterNetlessReanimated(tChar)) or (findTargetReanimModel(targetPlr) ~= nil)
        if (tHum and tHum.Health <= 0) and not isLoopReanim then break end
        tRef  = tChar and pickTargetRef(tChar, refMode or "torso")
        if tRef and tRef.Parent and not isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
            WeldSeekingTarget = prevSeeking
            return snapToFoundRef(tChar, tRef)
        end
        local targetCF = getBestTargetCFrame(targetPlr)
        if targetCF and not isLethalVoidCF(targetCF) then
            local now = tick()
            if now - lastStreamCall > 0.22 then
                lastStreamCall = now
                task.spawn(function()
                    pcall(function() LP:RequestStreamAroundAsync(targetCF.Position, 1.5) end)
                end)
            end
            myChar = LP.Character
            myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
            if myRoot then
                didTeleportFromOrigin = true
                moveState.lastTeleportTick = tick()
                for _, v in ipairs(myChar:GetChildren()) do
                    if v:IsA("BasePart") then v.CanCollide = false end
                end
                myRoot.AssemblyLinearVelocity = Vector3.zero
                myRoot.AssemblyAngularVelocity = Vector3.zero
                myRoot.CFrame = targetCF * CFrame.new(0, 2, 0)
            end
        else
            break
        end
        RunService.Heartbeat:Wait()
    end

    tChar = findPlayerCharacterAnywhere(targetPlr)
    tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
    local isReanimMid = (tChar and isCharacterNetlessReanimated(tChar)) or (findTargetReanimModel(targetPlr) ~= nil)
    tRef  = (isReanimMid or not (tHum and tHum.Health <= 0)) and tChar and pickTargetRef(tChar, refMode or "torso") or nil
    if tRef and tRef.Parent and not isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
        WeldSeekingTarget = prevSeeking
        return snapToFoundRef(tChar, tRef)
    end

    -- Step 2: Sweep map points ONLY if the target character has 0 streamed BaseParts in workspace (never sweep when target is reanimating or invisible in-place!)
    local hasStreamedPartsNow = (tChar and tChar:FindFirstChildWhichIsA("BasePart", true) ~= nil)
    if allowSweep and not hasStreamedPartsNow and not isReanimMid and (not tHum or tHum.Health > 0) then
        local probePoints = getServerSweepPoints and getServerSweepPoints() or {}
        for idx, probeCF in ipairs(probePoints) do
            if tick() - started > maxWaitSeconds or idx > 14 then break end
            if targetPlr.Parent ~= Players then break end
            tChar = findPlayerCharacterAnywhere(targetPlr)
            tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
            local isSweepReanim = (tChar and isCharacterNetlessReanimated(tChar)) or (findTargetReanimModel(targetPlr) ~= nil)
            if (tHum and tHum.Health <= 0) and not isSweepReanim then break end
            tRef  = tChar and pickTargetRef(tChar, refMode or "torso")
            if tRef and tRef.Parent and not isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
                WeldSeekingTarget = prevSeeking
                return snapToFoundRef(tChar, tRef)
            end
            if tChar and tChar:FindFirstChildWhichIsA("BasePart", true) ~= nil then
                break
            end
            local knownCF = getBestTargetCFrame(targetPlr)
            local hopCF = (knownCF and isValidTargetWorldCF(knownCF)) and knownCF or probeCF
            if hopCF and isSafePlayableCF(hopCF) then
                local now = tick()
                if now - lastStreamCall > 0.22 then
                    lastStreamCall = now
                    task.spawn(function()
                        pcall(function() LP:RequestStreamAroundAsync(hopCF.Position, 1.0) end)
                    end)
                end
                myChar = LP.Character
                myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
                if myRoot then
                    didTeleportFromOrigin = true
                    moveState.lastTeleportTick = tick()
                    for _, v in ipairs(myChar:GetChildren()) do
                        if v:IsA("BasePart") then v.CanCollide = false end
                    end
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    myRoot.AssemblyAngularVelocity = Vector3.zero
                    myRoot.CFrame = hopCF + Vector3.new(0, 3, 0)
                end
            end
            RunService.Heartbeat:Wait()
        end
    end

    WeldSeekingTarget = prevSeeking
    tChar = findPlayerCharacterAnywhere(targetPlr)
    tHum  = tChar and tChar:FindFirstChildOfClass("Humanoid")
    local isEndReanim = (tChar and isCharacterNetlessReanimated(tChar)) or (findTargetReanimModel(targetPlr) ~= nil)
    tRef  = (isEndReanim or not (tHum and tHum.Health <= 0)) and tChar and pickTargetRef(tChar, refMode or "torso") or nil
    if tRef and tRef.Parent and not isLethalVoidCF(tRef.CFrame, tRef.AssemblyLinearVelocity) then
        return snapToFoundRef(tChar, tRef)
    end

    if didTeleportFromOrigin and LP.Character and CurrentWeld == nil then
        recoverCharacterState(LP.Character, originSafeCF)
    end
    return tChar, nil
end

local getNearestPlayer
;(function()
    local ProximityPromptService = nil
    pcall(function() ProximityPromptService = game:GetService("ProximityPromptService") end)

    -- Tracks players recently interacted with or carried via ProximityPrompt or Interact/Carry UI buttons
    local InteractedCarryPlayers = {} -- [userId] = { triggeredAt = number, lastNearAt = number }

    local CARRY_INTERACT_KEYWORDS = {
        "carry", "carried", "carrying", "carrier",
        "interact", "interacting", "interaction",
        "piggyback", "cradle", "shoulder", "bridal",
        "hug", "hugging", "cuddle", "hold", "holding", "held",
        "grab", "grabbed", "grabbing", "pickup", "pick up", "lift",
        "sync", "synced", "couple", "coupled", "partner", "paired", "duet",
        "weld", "welded", "attached", "linked"
    }

    local RELEASE_KEYWORDS = {
        "drop", "release", "put down", "putdown", "uncarry", "stop carry", "stop interact", "let go", "detach"
    }

    local function textMatchesAny(str, wordList)
        if type(str) ~= "string" or str == "" then return false end
        local low = str:lower()
        for i = 1, #wordList do
            if low:find(wordList[i], 1, true) then
                return true
            end
        end
        return false
    end

    local function getPlayerFromInstance(inst)
        if not inst then return nil end
        local cur = inst
        while cur and cur ~= workspace and cur ~= game do
            if cur:IsA("Player") then return cur end
            if cur:IsA("Model") then
                local plr = Players:GetPlayerFromCharacter(cur)
                if plr then return plr end
                local byExact = Players:FindFirstChild(cur.Name)
                if byExact and byExact:IsA("Player") then return byExact end
            end
            if cur:IsA("BillboardGui") or cur:IsA("SurfaceGui") or cur:IsA("ProximityPrompt") then
                local adornee = nil
                pcall(function() adornee = cur.Adornee end)
                if adornee then
                    local aCur = adornee
                    while aCur and aCur ~= workspace and aCur ~= game do
                        if aCur:IsA("Model") then
                            local aPlr = Players:GetPlayerFromCharacter(aCur) or Players:FindFirstChild(aCur.Name)
                            if aPlr and aPlr:IsA("Player") then return aPlr end
                        end
                        aCur = aCur.Parent
                    end
                end
            end
            cur = cur.Parent
        end
        return nil
    end

    local function findClosestPlayerWithin(originPos, maxDist, excludePlr)
        local bestP, bestD = nil, maxDist or 14
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p ~= excludePlr then
                local c = findPlayerCharacterAnywhere(p, true)
                local r = c and pickTargetRef(c, "torso")
                if r and r.Parent then
                    local d = (r.Position - originPos).Magnitude
                    if d <= bestD then
                        bestD = d
                        bestP = p
                    end
                end
            end
        end
        return bestP
    end

    local function markPlayerInteractedOrCarried(plr)
        if not plr or plr == LP or not plr.UserId then return end
        local now = tick()
        InteractedCarryPlayers[plr.UserId] = {
            triggeredAt = now,
            lastNearAt = now,
        }
    end

    local function clearPlayerInteractedOrCarried(plr)
        if not plr or not plr.UserId then return end
        InteractedCarryPlayers[plr.UserId] = nil
    end

    if ProximityPromptService then
        local function onPromptInteraction(prompt, playerWhoTriggered)
            if playerWhoTriggered and playerWhoTriggered ~= LP then return end
            if not prompt then return end
            pcall(function()
                local combinedText = tostring(prompt.ActionText or "") .. " " .. tostring(prompt.ObjectText or "") .. " " .. tostring(prompt.Name or "")
                local ownerPlr = getPlayerFromInstance(prompt)
                local myChar = LP.Character
                local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))

                if textMatchesAny(combinedText, RELEASE_KEYWORDS) then
                    if ownerPlr and ownerPlr ~= LP then
                        clearPlayerInteractedOrCarried(ownerPlr)
                    else
                        for uid, _ in pairs(InteractedCarryPlayers) do
                            InteractedCarryPlayers[uid] = nil
                        end
                    end
                    return
                end

                if ownerPlr and ownerPlr ~= LP then
                    markPlayerInteractedOrCarried(ownerPlr)
                    return
                end

                if textMatchesAny(combinedText, CARRY_INTERACT_KEYWORDS) then
                    local promptPos = nil
                    local pParent = prompt.Parent
                    if pParent and pParent:IsA("BasePart") then
                        promptPos = pParent.Position
                    elseif pParent and pParent:IsA("Attachment") then
                        promptPos = pParent.WorldPosition
                    elseif pParent and pParent:IsA("Model") then
                        local okP, piv = pcall(function() return pParent:GetPivot() end)
                        if okP and piv then promptPos = piv.Position end
                    end
                    local refPos = promptPos or (myRoot and myRoot.Position)
                    if refPos then
                        local nearP = findClosestPlayerWithin(refPos, 14)
                        if nearP then
                            markPlayerInteractedOrCarried(nearP)
                        end
                    end
                end
            end)
        end
        pcall(function() ProximityPromptService.PromptTriggered:Connect(onPromptInteraction) end)
        pcall(function() ProximityPromptService.PromptButtonHoldEnded:Connect(onPromptInteraction) end)
    end

    local hookedGuiButtons = setmetatable({}, { __mode = "k" })
    local function inspectAndHookGuiButton(btn)
        if not btn or hookedGuiButtons[btn] then return end
        if not (btn:IsA("TextButton") or btn:IsA("ImageButton")) then return end
        local anc = btn
        while anc do
            if anc.Name:match("^Coco") then return end
            anc = anc.Parent
        end
        hookedGuiButtons[btn] = true
        pcall(function()
            btn.Activated:Connect(function()
                pcall(function()
                    local txt = ""
                    if btn:IsA("TextButton") then txt = tostring(btn.Text or "") end
                    for _, desc in ipairs(btn:GetDescendants()) do
                        if desc:IsA("TextLabel") or desc:IsA("TextButton") then
                            txt = txt .. " " .. tostring(desc.Text or "")
                        end
                    end
                    local fullStr = txt .. " " .. tostring(btn.Name or "") .. " " .. tostring(btn.Parent and btn.Parent.Name or "")
                    if textMatchesAny(fullStr, RELEASE_KEYWORDS) then
                        for uid, _ in pairs(InteractedCarryPlayers) do
                            InteractedCarryPlayers[uid] = nil
                        end
                        return
                    end
                    local adorneePlr = getPlayerFromInstance(btn)
                    if adorneePlr and adorneePlr ~= LP then
                        markPlayerInteractedOrCarried(adorneePlr)
                        return
                    end
                    if textMatchesAny(fullStr, CARRY_INTERACT_KEYWORDS) then
                        local menuRoot = btn.Parent and btn.Parent.Parent or btn.Parent
                        if menuRoot then
                            for _, d in ipairs(menuRoot:GetDescendants()) do
                                if d:IsA("TextLabel") or d:IsA("TextButton") then
                                    local dTxt = tostring(d.Text or ""):lower()
                                    if dTxt ~= "" then
                                        for _, p in ipairs(Players:GetPlayers()) do
                                            if p ~= LP and (dTxt:find(p.Name:lower(), 1, true) or (p.DisplayName ~= "" and dTxt:find(p.DisplayName:lower(), 1, true))) then
                                                markPlayerInteractedOrCarried(p)
                                                return
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        local myChar = LP.Character
                        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
                        if myRoot then
                            local nearP = findClosestPlayerWithin(myRoot.Position, 14)
                            if nearP then
                                markPlayerInteractedOrCarried(nearP)
                            end
                        end
                    end
                end)
            end)
        end)
    end

    pcall(function()
        local pgui = LP:FindFirstChildOfClass("PlayerGui")
        if pgui then
            pgui.DescendantAdded:Connect(function(obj)
                if obj:IsA("TextButton") or obj:IsA("ImageButton") then
                    inspectAndHookGuiButton(obj)
                end
            end)
            task.spawn(function()
                local list = pgui:GetDescendants()
                for idx, obj in ipairs(list) do
                    if obj:IsA("TextButton") or obj:IsA("ImageButton") then
                        inspectAndHookGuiButton(obj)
                    end
                    if idx % 600 == 0 then
                        RunService.Heartbeat:Wait()
                    end
                end
            end)
        end
    end)

    LP.CharacterAdded:Connect(function()
        InteractedCarryPlayers = {}
    end)

    local function valueReferencesPlayer(val, targetPlr, targetChar)
        if val == nil or not targetPlr then return false end
        local t = typeof(val)
        if t == "Instance" then
            if val == targetPlr or (targetChar and (val == targetChar or val:IsDescendantOf(targetChar))) then
                return true
            end
        elseif t == "number" then
            if val == targetPlr.UserId then return true end
        elseif t == "string" and val ~= "" then
            local low = val:lower()
            local pName = (targetPlr.Name or ""):lower()
            local pDisp = (targetPlr.DisplayName or ""):lower()
            local uidStr = tostring(targetPlr.UserId)
            if low == pName or (pDisp ~= "" and low == pDisp) or low == uidStr then
                return true
            end
            if pName ~= "" and low:find(pName, 1, true) then
                return true
            end
        end
        return false
    end

    local function hasCrossReferenceOrCarryState(sourceInst, targetPlr, targetChar, isCloseEnough)
        if not sourceInst then return false end
        local okAttr, attrs = pcall(function() return sourceInst:GetAttributes() end)
        if okAttr and attrs then
            for k, v in pairs(attrs) do
                if valueReferencesPlayer(v, targetPlr, targetChar) then
                    return true
                end
                if isCloseEnough and textMatchesAny(tostring(k), CARRY_INTERACT_KEYWORDS) then
                    if v == true or (type(v) == "number" and v ~= 0) or (type(v) == "string" and v ~= "" and v:lower() ~= "none" and v:lower() ~= "false") then
                        return true
                    end
                end
            end
        end
        for _, child in ipairs(sourceInst:GetDescendants()) do
            if child:IsA("ValueBase") then
                local okV, v = pcall(function() return child.Value end)
                if okV then
                    if valueReferencesPlayer(v, targetPlr, targetChar) then
                        return true
                    end
                    if isCloseEnough and textMatchesAny(child.Name, CARRY_INTERACT_KEYWORDS) then
                        if v == true or (typeof(v) == "Instance") or (type(v) == "number" and v ~= 0) or (type(v) == "string" and v ~= "" and v:lower() ~= "none" and v:lower() ~= "false") then
                            return true
                        end
                    end
                end
            end
        end
        return false
    end

    local function isJointOrConstraintBetween(obj, charA, charB)
        if not obj or not charA or not charB then return false end
        if obj:IsA("JointInstance") or obj:IsA("WeldConstraint") then
            local p0, p1 = obj.Part0, obj.Part1
            if p0 and p1 then
                if (p0:IsDescendantOf(charA) and p1:IsDescendantOf(charB))
                    or (p1:IsDescendantOf(charA) and p0:IsDescendantOf(charB)) then
                    return true
                end
            end
        elseif obj:IsA("Constraint") then
            local a0, a1 = obj.Attachment0, obj.Attachment1
            if a0 and a1 then
                if (a0:IsDescendantOf(charA) and a1:IsDescendantOf(charB))
                    or (a1:IsDescendantOf(charA) and a0:IsDescendantOf(charB)) then
                    return true
                end
            end
        end
        return false
    end

    local CarryCheckCache = {}

    -- Strictly detect ONLY genuine physical carry welds/parenting between speaker and p
    -- (Eliminates false-positive skipping of nearby players in getNearestPlayer & resolveActiveTarget!)
    local function isPlayerCarriedOrInteracting(p, speaker)
        speaker = speaker or LP
        if not p or p == speaker or p.Parent ~= Players then return false end

        -- Never exclude a target that is selected or that CocoPowder itself is actively welding/flinging/copying
        if p == selectedPlayer
            or p == CurrentTarget
            or (WeldIntent and WeldIntent.target == p)
            or (AnimCopySys and AnimCopySys.target == p) then
            return false
        end

        local now = os.clock()
        local cacheKey = tostring(speaker.UserId) .. "_" .. tostring(p.UserId)
        local cached = CarryCheckCache[cacheKey]
        if cached and (now - cached.t) < 0.25 then
            return cached.v
        end

        local myChar = speaker and speaker.Character
        local tChar  = findPlayerCharacterAnywhere(p, true)
        if not myChar or not tChar then
            CarryCheckCache[cacheKey] = { t = now, v = false }
            return false
        end

        -- 1. Direct character hierarchy parenting
        if tChar:IsDescendantOf(myChar) or myChar:IsDescendantOf(tChar) then
            CarryCheckCache[cacheKey] = { t = now, v = true }
            return true
        end

        local myRoot = myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart")
        local tRoot  = pickTargetRef(tChar, "torso")
        local dist   = (myRoot and tRoot) and (tRoot.Position - myRoot.Position).Magnitude or math.huge
        if dist > 6.5 then
            CarryCheckCache[cacheKey] = { t = now, v = false }
            return false
        end

        local myHum = myChar:FindFirstChildOfClass("Humanoid")
        local tHum  = tChar:FindFirstChildOfClass("Humanoid")
        if (tHum and tHum.SeatPart and tHum.SeatPart:IsDescendantOf(myChar))
            or (myHum and myHum.SeatPart and myHum.SeatPart:IsDescendantOf(tChar)) then
            CarryCheckCache[cacheKey] = { t = now, v = true }
            return true
        end

        -- 2. Friends & Whitelist Ignore Check (for Auto-Nearest & Pursuit)
        if _G.CocoIgnoreFriends and speaker == LP then
            if (_G.CocoTargetWhitelist and _G.CocoTargetWhitelist[p.UserId]) then
                CarryCheckCache[cacheKey] = { t = now, v = true }
                return true
            end
            local okFr, isFr = pcall(function() return LP:IsFriendsWith(p.UserId) end)
            if okFr and isFr then
                CarryCheckCache[cacheKey] = { t = now, v = true }
                return true
            end
        elseif _G.CocoTargetWhitelist and _G.CocoTargetWhitelist[p.UserId] and speaker == LP then
            CarryCheckCache[cacheKey] = { t = now, v = true }
            return true
        end

        -- 3. Shared rigid physics assembly (when CocoPowder is not welding)
        local result = false
        if myRoot and tRoot and CurrentWeld == nil then
            local okAssy, sameAssy = pcall(function()
                local a1 = myRoot.AssemblyRootPart
                local a2 = tRoot.AssemblyRootPart
                return (a1 ~= nil and a1 == a2)
            end)
            if okAssy and sameAssy then
                result = true
            end
        end

        CarryCheckCache[cacheKey] = { t = now, v = result }
        return result
    end

    OwnerAdminState.isPlayerCarriedOrInteracting = isPlayerCarriedOrInteracting

    getNearestPlayer = function(speaker)
        speaker = speaker or LP
        local myChar = speaker and speaker.Character
        local myRoot = myChar and (myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart"))
        local myPos  = myRoot and myRoot.Position or Vector3.zero
        local bestPlr, bestDist = nil, math.huge

        -- 1. First pass: strictly prioritize players whose real Character BasePart is currently streamed in!
        --    (Excludes any player currently carried or interacted with by speaker!)
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= speaker and not isPlayerCarriedOrInteracting(p, speaker) then
                local c = findPlayerCharacterAnywhere(p)
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local streamedCF = getVerifiedStreamedCFrame(p)
                if streamedCF and (not h or h.Health > 0) then
                    local d = (streamedCF.Position - myPos).Magnitude
                    if d < bestDist then
                        bestDist = d
                        bestPlr = p
                    end
                end
            end
        end
        if bestPlr then return bestPlr, bestDist end

        -- 2. Second pass: if no players are streamed in near us, check known/cached player positions
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= speaker and not isPlayerCarriedOrInteracting(p, speaker) then
                local c = findPlayerCharacterAnywhere(p)
                local h = c and c:FindFirstChildOfClass("Humanoid")
                local cf = getBestTargetCFrame(p)
                if cf and (not h or h.Health > 0) then
                    local d = (cf.Position - myPos).Magnitude
                    if d < bestDist then
                        bestDist = d
                        bestPlr = p
                    end
                end
            end
        end

        -- 3. Fallback: even if all players are hiding in unstreamed chunks, still return a valid server player (excluding carried/interacted)!
        if not bestPlr then
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= speaker and not isPlayerCarriedOrInteracting(p, speaker) then
                    return p, math.huge
                end
            end
        end
        return bestPlr, bestDist
    end
end)()

local function findPlayerByNameOrDisplay(query, speaker)
    speaker = speaker or LP
    if not query then return nil end
    local q = tostring(query):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
    if q == "" then return nil end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= speaker and (p.Name:lower() == q or p.DisplayName:lower() == q) then
            return p
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= speaker and (p.Name:lower():sub(1, #q) == q or p.DisplayName:lower():sub(1, #q) == q) then
            return p
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= speaker and (p.Name:lower():find(q, 1, true) or p.DisplayName:lower():find(q, 1, true)) then
            return p
        end
    end
    return nil
end

local WeldUsernameBoxRef = nil

local function resolveActiveTarget()
    -- 1. If WeldUsernameBox is currently focused and the user is actively typing a valid player name, check it first
    if WeldUsernameBoxRef and WeldUsernameBoxRef.Parent and WeldUsernameBoxRef:IsFocused() then
        local rawFocused = (WeldUsernameBoxRef.Text or ""):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if rawFocused ~= "" then
            local byFocused = findPlayerByNameOrDisplay(rawFocused, LP)
            if byFocused and byFocused.Parent == Players and byFocused ~= LP then
                selectedPlayer = byFocused
                CurrentTarget = byFocused
                return byFocused, false
            end
        end
    end
    -- 2. Prioritize explicitly locked selectedPlayer from Target tab / Quick List (never blocked by stale textbox state!)
    if selectedPlayer and selectedPlayer.Parent == Players and selectedPlayer ~= LP then
        return selectedPlayer, false
    end
    -- 3. Check live text inside WeldUsernameBox on the Weld tab
    if WeldUsernameBoxRef and WeldUsernameBoxRef.Parent then
        local rawBox = (WeldUsernameBoxRef.Text or ""):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if rawBox ~= "" then
            local byBox = findPlayerByNameOrDisplay(rawBox, LP)
            if byBox and byBox.Parent == Players and byBox ~= LP then
                selectedPlayer = byBox
                CurrentTarget = byBox
                return byBox, false
            end
        end
    end
    -- 4. Check CurrentTarget / WeldIntent.target if still in server
    if CurrentTarget and CurrentTarget.Parent == Players and CurrentTarget ~= LP and WeldIntent.typedUsername ~= "" then
        selectedPlayer = CurrentTarget
        return CurrentTarget, false
    end
    -- 5. Check Chat tab target input if non-empty
    if chatTargetInput and chatTargetInput.Parent then
        local typed = (chatTargetInput.Text or ""):gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
        if typed ~= "" then
            local byName = findPlayerByNameOrDisplay(typed, LP)
            if byName and byName.Parent == Players then
                return byName, false
            end
        end
    end
    -- 6. Auto-Nearest Player fallback
    local nearest = getNearestPlayer(LP)
    return nearest, true
end

local function resolvePlayer(target, speaker)
    speaker = speaker or LP
    if typeof(target) == "Instance" and target:IsA("Player") then
        if target.Parent == Players and target ~= speaker then return target end
    elseif target ~= nil and tostring(target) ~= "" then
        local found = findPlayerByNameOrDisplay(target, speaker)
        if found and found.Parent == Players and found ~= speaker then return found end
    end
    local activeTgt = resolveActiveTarget()
    if activeTgt and activeTgt.Parent == Players and activeTgt ~= speaker then
        return activeTgt
    end
    return getNearestPlayer(speaker)
end

