_G.AddCocoCustomRoast = function(word)
    word = tostring(word or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if word == "" then return false end
    table.insert(CS_W, 1, word:upper())
    table.insert(_G.CocoCustomRoasts, word:upper())
