local avStart, avStop, akStart, akStop, agpStart, agpStop, afkStart, afkStop, vcStart, vcStop
local ragdollStart, ragdollStop, anchorStart, anchorStop, attachStart, attachStop, blindStart, blindStop
local bringStart, bringStop, flingShieldStart, flingShieldStop, redirectStart, redirectStop, pauseTrapStart, pauseTrapStop
local defenceTrollStart, defenceTrollStop, enableAllAntiSystems, disableAllAntiSystems
;(function() -- Scoped block for internal Anti helper functions (frees 35+ top-level local registers)
-- 1. ADVANCED ANTI-VOID V4 (Zero-Levitation Predictive Void Catch + Undying State Guard)
-- ═══════════════════════════════════════════════════════════════════════════════
local function avEnsureSafetyFloor(pos)
    local floor = Anti.Void.safetyFloor
    if not floor or not floor.Parent then
        floor = Instance.new("Part")
        floor.Name = "CocoVoidSafetyFloor"
        floor.Anchored = true
        floor.CanCollide = true
        floor.CanTouch = false
        floor.CanQuery = false
        floor.Size = Vector3.new(64, 2, 64)
        floor.Transparency = 0.75
        floor.Material = Enum.Material.ForceField
        floor.Color = Color3.fromRGB(138, 92, 246)
        floor.Parent = workspace
        Anti.Void.safetyFloor = floor
    end
    floor.CFrame = CFrame.new(pos.X, pos.Y - 4.0, pos.Z)
end

local function avRemoveSafetyFloor()
    if Anti.Void.safetyFloor then
        pcall(function() Anti.Void.safetyFloor:Destroy() end)
        Anti.Void.safetyFloor = nil
    end
end

local function avForceAlive(h)
    if not h or not h.Parent then return end
    local isReanimActive = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
    pcall(function()
        pcall(function() h.BreakJointsOnDeath = false end)
        -- Only call SetStateEnabled when state is currently enabled to avoid dirtying Roblox's C++ Humanoid state machine!
        if h:GetStateEnabled(Enum.HumanoidStateType.Dead) then
            h:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        end
        if h:GetStateEnabled(Enum.HumanoidStateType.FallingDown) then
            h:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        end
        if h:GetStateEnabled(Enum.HumanoidStateType.Ragdoll) then
            h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
        end
        if h:GetStateEnabled(Enum.HumanoidStateType.Seated) then
            h:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
        end
        if h.MaxHealth <= 0 or h.MaxHealth ~= h.MaxHealth or h.MaxHealth == math.huge then
            h.MaxHealth = 100
        end
        if h.Health <= 0 or h.Health < h.MaxHealth or h.Health ~= h.Health then
            h.Health = h.MaxHealth
        end
        if h.PlatformStand and not (moveState and (moveState.fly or moveState.flyLanding)) and CurrentWeld == nil and not WeldSeekingTarget and not isReanimActive then
            h.PlatformStand = false
        end
        if h.Sit then h.Sit = false end
        if h:GetState() == Enum.HumanoidStateType.Dead then
            h:ChangeState(Enum.HumanoidStateType.Running)
        end
    end)
end

local function avHookHumanoid(h)
    if not h or not h.Parent then return end
    avForceAlive(h)
    table.insert(Anti.Void.healthConns, h.HealthChanged:Connect(function(hp)
        if (Anti.Void.enabled or Anti.Kill.enabled) and (hp <= 0 or hp < h.MaxHealth) then
            avForceAlive(h)
        end
    end))
    table.insert(Anti.Void.healthConns, h.StateChanged:Connect(function(_, newState)
        if (Anti.Void.enabled or Anti.Kill.enabled) and newState == Enum.HumanoidStateType.Dead then
            avForceAlive(h)
        end
    end))
end

local function avHookChar(c)
    if not c then return end
    for _, x in ipairs(Anti.Void.charConns) do pcall(function() x:Disconnect() end) end
    Anti.Void.charConns = {}
    for _, x in ipairs(Anti.Void.healthConns) do pcall(function() x:Disconnect() end) end
    Anti.Void.healthConns = {}
    local hum = c:FindFirstChildOfClass("Humanoid")
    if hum then avHookHumanoid(hum) end
    table.insert(Anti.Void.charConns, c.ChildAdded:Connect(function(ch)
        if ch:IsA("Humanoid") then avHookHumanoid(ch) end
    end))
end

avStart = function(silent)
    if Anti.Void.enabled and Anti.Void.steppedConn and Anti.Void.loopConn then
        if syncAllAntiButtons then pcall(syncAllAntiButtons) end
        return
    end
    Anti.Void.enabled = true
    pcall(function() workspace.FallenPartsDestroyHeight = 0/0 end)
    avHookChar(LP.Character)
    if Anti.Void.charAdded then Anti.Void.charAdded:Disconnect() end
    Anti.Void.charAdded = LP.CharacterAdded:Connect(function(c)
        if not Anti.Void.enabled then return end
        task.wait(0.15)
        avHookChar(c)
    end)
    if Anti.Void.steppedConn then Anti.Void.steppedConn:Disconnect() end
    Anti.Void.steppedConn = RunService.Stepped:Connect(function()
        if not Anti.Void.enabled then return end
        local c = LP.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        local h = c and c:FindFirstChildOfClass("Humanoid")
        if h and (h.Health <= 0 or h.Health < h.MaxHealth) then
            avForceAlive(h)
        end
        if not r or FlingActive or deflectBusy or CurrentWeld ~= nil or WeldSeekingTarget or (AnimCopySys and AnimCopySys.active) or (moveState and moveState.Vanish and moveState.Vanish.selfActive) or _G.CocaBangActive or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated())) or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) or (RewindSys and RewindSys.rewinding) then return end
        local pos = r.Position
        local vel = r.AssemblyLinearVelocity
        local dangerFloor = math.min(OriginalFPDH + 45, -220)
        local predictedY = pos.Y + (vel.Y * 0.045)
        -- Predictive deep-void rescue: catches true void falls without spawning floating platforms on normal maps
        if pos.Y <= dangerFloor or predictedY <= dangerFloor or (pos.Y <= (dangerFloor + 30) and vel.Y < -130) or pos.Magnitude > 100000 or pos.X ~= pos.X then
            r.AssemblyLinearVelocity = Vector3.new(vel.X * 0.05, 0, vel.Z * 0.05)
            r.AssemblyAngularVelocity = Vector3.zero
            if not isSafePlayableCF(LastKnownSafeCF) then
                avEnsureSafetyFloor(Vector3.new(pos.X, math.max(pos.Y, dangerFloor + 12), pos.Z))
            end
            Anti.Void.rescues = Anti.Void.rescues + 1
            markIntentionalTeleport(LastKnownSafeCF)
            safeReturnFromVoid(c, LastKnownSafeCF)
        elseif Anti.Void.safetyFloor and (pos.Y > dangerFloor + 40 or (h and h.FloorMaterial ~= Enum.Material.Air)) then
            avRemoveSafetyFloor()
        end
    end)
    if Anti.Void.loopConn then Anti.Void.loopConn:Disconnect() end
    local lastHealthGuard = 0
    Anti.Void.loopConn = RunService.Heartbeat:Connect(function()
        if not Anti.Void.enabled then return end
        local now = tick()
        if now - lastHealthGuard < 0.20 then return end
        lastHealthGuard = now
        local c = LP.Character
        if not c then return end
        local h = c:FindFirstChildOfClass("Humanoid")
        if h then avForceAlive(h) end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    if not silent then
        notify("COCO POWDER", "Anti-Void v4 (Zero-Levitation Predictive Void Catch) ON")
        sToggleOn()
    end
end

avStop = function()
    if Anti.lockAlwaysOn then
        if not Anti.Void.enabled or not Anti.Void.steppedConn or not Anti.Void.loopConn then
            avStart(true)
        end
        if syncAllAntiButtons then pcall(syncAllAntiButtons) end
        if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
        notify("COCO POWDER", "Anti-Void is locked as Always-On (unlock in Anti Shield tab to disable)!")
        sToggleOn()
        return
    end
    Anti.Void.enabled = false
    if Anti.Void.steppedConn then Anti.Void.steppedConn:Disconnect(); Anti.Void.steppedConn = nil end
    if Anti.Void.loopConn then Anti.Void.loopConn:Disconnect(); Anti.Void.loopConn = nil end
    if Anti.Void.charAdded then Anti.Void.charAdded:Disconnect(); Anti.Void.charAdded = nil end
    avRemoveSafetyFloor()
    if not (Anti.Kill and Anti.Kill.enabled) then
        pcall(function() workspace.FallenPartsDestroyHeight = OriginalFPDH end)
    end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
    notify("COCO POWDER", "Anti-Void disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2. IMMORTAL GOD-CORE & ANTI-KILL V4 ("NOTHING CAN KILL YOU IN GAME")
--    • Layer 1: Zero KillBrick / Lava / Projectile Touch (CanTouch = false, while keeping
--               CanQuery = true & Massless = false so ground raycasts & gravity never float!)
--    • Layer 2: BreakJointsOnDeath = false + Instant Motor6D / Neck Resurrection (blocks
--               decapitation, sword BreakJoints, and explosion joint destruction in 0ms)
--    • Layer 3: Sub-Frame Undying Health Lock (blocks Dead state & instant-heal on damage)
--    • Layer 4: Explosion & Hazard Part Neutralizer (BlastPressure = 0, BlastRadius = 0)
-- ═══════════════════════════════════════════════════════════════════════════════
Anti.Kill.partTouchConns = Anti.Kill.partTouchConns or setmetatable({}, {__mode = "k"})
Anti.Kill.motorCache = Anti.Kill.motorCache or setmetatable({}, {__mode = "k"})
Anti.Kill.motorConns = Anti.Kill.motorConns or {}

local function akIsHazardPartName(name)
    if type(name) ~= "string" then return false end
    local low = name:lower()
    return low:find("kill", 1, true)
        or low:find("lava", 1, true)
        or low:find("laser", 1, true)
        or low:find("acid", 1, true)
        or low:find("poison", 1, true)
        or low:find("spike", 1, true)
        or low:find("death", 1, true)
        or low:find("damage", 1, true)
        or low:find("instakill", 1, true) ~= nil
end

local function akSanitizePart(p)
    if not (p and p:IsA("BasePart")) then return end
    local saved = Anti.Kill.originalPartFlags[p]
    if not saved then
        saved = { CanTouch = p.CanTouch }
        Anti.Kill.originalPartFlags[p] = saved
    end
    pcall(function()
        if p.CanTouch then p.CanTouch = false end
        -- Keep CanQuery = true so floor/stair raycasts & character ground sensors never levitate!
    end)
    if not Anti.Kill.partTouchConns[p] then
        Anti.Kill.partTouchConns[p] = p:GetPropertyChangedSignal("CanTouch"):Connect(function()
            if Anti.Kill.enabled and p.Parent and p.CanTouch then
                pcall(function() p.CanTouch = false end)
            end
        end)
    end
end

local function akSnapshotAndGuardMotor(m, char)
    if not (m and m:IsA("Motor6D") and char) then return end
    if m.Part0 and m.Part1 then
        Anti.Kill.motorCache[m] = {
            Name = m.Name,
            Parent = m.Parent,
            Part0 = m.Part0,
            Part1 = m.Part1,
            C0 = m.C0,
            C1 = m.C1,
        }
    end
    local conn = m.Changed:Connect(function(prop)
        if not Anti.Kill.enabled or not char.Parent then return end
        local isReanim = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
            or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        if isReanim then return end
        local info = Anti.Kill.motorCache[m]
        if not info then return end
        if prop == "Enabled" and not m.Enabled then
            pcall(function() m.Enabled = true end)
        elseif (prop == "Part0" or prop == "Part1") and (m.Part0 == nil or m.Part1 == nil) then
            if info.Part0 and info.Part0.Parent and info.Part1 and info.Part1.Parent then
                pcall(function()
                    m.Part0 = info.Part0
                    m.Part1 = info.Part1
                end)
            end
        end
    end)
    table.insert(Anti.Kill.motorConns, conn)
end

local function akApply(char)
    if not char then return end
    for _, p in ipairs(char:GetDescendants()) do
        if p:IsA("BasePart") then
            akSanitizePart(p)
        elseif p:IsA("Motor6D") then
            akSnapshotAndGuardMotor(p, char)
        elseif (p:IsA("Fire") or p:IsA("Smoke")) and not p.Name:match("^Coco") then
            pcall(function() p.Enabled = false end)
        end
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        avForceAlive(hum)
    end
end

local function akHookCharacter(char)
    if Anti.Kill.descConn then Anti.Kill.descConn:Disconnect(); Anti.Kill.descConn = nil end
    if Anti.Kill.remConn then Anti.Kill.remConn:Disconnect(); Anti.Kill.remConn = nil end
    for _, c in ipairs(Anti.Kill.motorConns) do pcall(function() c:Disconnect() end) end
    Anti.Kill.motorConns = {}
    if not char then return end
    akApply(char)
    Anti.Kill.descConn = char.DescendantAdded:Connect(function(obj)
        if not Anti.Kill.enabled then return end
        if obj:IsA("BasePart") then
            akSanitizePart(obj)
        elseif obj:IsA("Motor6D") then
            akSnapshotAndGuardMotor(obj, char)
        elseif obj:IsA("Humanoid") then
            avHookHumanoid(obj)
        elseif obj:IsA("ObjectValue") and (obj.Name:lower() == "creator" or obj.Name:lower():find("damage", 1, true) or obj.Name:lower():find("kill", 1, true)) then
            task.defer(function() pcall(function() obj:Destroy() end) end)
        end
    end)
    -- Instant Motor6D / Neck resurrection if BreakJoints() or an explosion destroys a character joint
    Anti.Kill.remConn = char.DescendantRemoving:Connect(function(obj)
        if not Anti.Kill.enabled or not char.Parent or char ~= LP.Character then return end
        local isReanim = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
            or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        if isReanim then return end
        if obj:IsA("Motor6D") then
            local info = Anti.Kill.motorCache[obj]
            if info and info.Parent and info.Parent.Parent and info.Part0 and info.Part0.Parent and info.Part1 and info.Part1.Parent then
                task.defer(function()
                    if not Anti.Kill.enabled or not char.Parent or char ~= LP.Character then return end
                    if info.Parent:FindFirstChild(info.Name) then return end
                    pcall(function()
                        local replacement = Instance.new("Motor6D")
                        replacement.Name = info.Name
                        replacement.Part0 = info.Part0
                        replacement.Part1 = info.Part1
                        replacement.C0 = info.C0
                        replacement.C1 = info.C1
                        replacement.Enabled = true
                        replacement.Parent = info.Parent
                        akSnapshotAndGuardMotor(replacement, char)
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        if hum then avForceAlive(hum) end
                    end)
                end)
            end
        end
    end)
end

akStart = function(silent)
    if Anti.Kill.enabled then
        if syncAllAntiButtons then pcall(syncAllAntiButtons) end
        return
    end
    Anti.Kill.enabled = true
    pcall(function() workspace.FallenPartsDestroyHeight = 0/0 end)
    akHookCharacter(LP.Character)
    if Anti.Kill.charAdded then Anti.Kill.charAdded:Disconnect() end
    Anti.Kill.charAdded = LP.CharacterAdded:Connect(function(char)
        if not Anti.Kill.enabled then return end
        task.defer(function() if Anti.Kill.enabled then akHookCharacter(char) end end)
    end)
    -- Neutralize workspace Explosions and obvious KillBricks / Lava TouchTransmitters
    if Anti.Kill.wsDescConn then Anti.Kill.wsDescConn:Disconnect() end
    Anti.Kill.wsDescConn = workspace.DescendantAdded:Connect(function(obj)
        if not Anti.Kill.enabled then return end
        if obj:IsA("Explosion") then
            pcall(function()
                obj.BlastPressure = 0
                obj.BlastRadius = 0
                obj.DestroyJointRadiusPercent = 0
            end)
        elseif obj:IsA("TouchTransmitter") and obj.Parent and obj.Parent:IsA("BasePart") then
            local p = obj.Parent
            if not (LP.Character and p:IsDescendantOf(LP.Character)) and akIsHazardPartName(p.Name) then
                pcall(function() p.CanTouch = false end)
            end
        end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    if not silent then
        notify("COCO POWDER", "🛡️ Immortal God-Core v4 ON (Undying Health + Neck Lock + Zero KillBrick Touch)")
        sToggleOn()
    end
end

akStop = function()
    if not Anti.Kill.enabled then return end
    Anti.Kill.enabled = false
    if Anti.Kill.charAdded then Anti.Kill.charAdded:Disconnect(); Anti.Kill.charAdded = nil end
    if Anti.Kill.descConn then Anti.Kill.descConn:Disconnect(); Anti.Kill.descConn = nil end
    if Anti.Kill.remConn then Anti.Kill.remConn:Disconnect(); Anti.Kill.remConn = nil end
    if Anti.Kill.wsDescConn then Anti.Kill.wsDescConn:Disconnect(); Anti.Kill.wsDescConn = nil end
    for _, c in ipairs(Anti.Kill.motorConns) do pcall(function() c:Disconnect() end) end
    Anti.Kill.motorConns = {}
    for part, conn in pairs(Anti.Kill.partTouchConns) do
        if conn then pcall(function() conn:Disconnect() end) end
        Anti.Kill.partTouchConns[part] = nil
    end
    for part, saved in pairs(Anti.Kill.originalPartFlags) do
        if part and part.Parent then
            pcall(function()
                part.CanTouch = saved.CanTouch
            end)
        end
        Anti.Kill.originalPartFlags[part] = nil
    end
    local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if hum and not (Anti.Void and Anti.Void.enabled) then
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true) end)
    end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Immortal God-Core / Anti-Kill disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 3. ADVANCED ANTI-GAMEPLAYPAUSED V2 (GuiService + CoreGui + Property Unfreeze)
-- ═══════════════════════════════════════════════════════════════════════════════
local function agpCleanse()
    pcall(function()
        game:GetService("GuiService"):SetGameplayPausedNotificationEnabled(false)
    end)
    pcall(function()
        if LP.GameplayPaused then LP.GameplayPaused = false end
    end)
    pcall(function()
        local rg = CoreGui and CoreGui:FindFirstChild("RobloxGui")
        if rg then
            local np = rg:FindFirstChild("CoreScripts/NetworkPause")
            if np then np:Destroy() end
        end
    end)
end

agpStart = function()
    if Anti.GamePaused.enabled then return end
    Anti.GamePaused.enabled = true
    agpCleanse()
    pcall(function()
        local rg = CoreGui and CoreGui:FindFirstChild("RobloxGui")
        if rg then
            if Anti.GamePaused.childAdded then Anti.GamePaused.childAdded:Disconnect() end
            Anti.GamePaused.childAdded = rg.ChildAdded:Connect(function(obj)
                if Anti.GamePaused.enabled and obj.Name:find("NetworkPause") then
                    pcall(function() obj:Destroy() end)
                end
            end)
        end
    end)
    if Anti.GamePaused.propConn then Anti.GamePaused.propConn:Disconnect() end
    pcall(function()
        Anti.GamePaused.propConn = LP:GetPropertyChangedSignal("GameplayPaused"):Connect(function()
            if Anti.GamePaused.enabled then
                pcall(function() LP.GameplayPaused = false end)
                agpCleanse()
            end
        end)
    end)
    if Anti.GamePaused.loopConn then Anti.GamePaused.loopConn:Disconnect() end
    Anti.GamePaused.loopConn = RunService.Heartbeat:Connect(function()
        if not Anti.GamePaused.enabled then return end
        if LP.GameplayPaused then
            pcall(function() LP.GameplayPaused = false end)
        end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-GameplayPaused v2 ON")
    sToggleOn()
end

agpStop = function()
    if not Anti.GamePaused.enabled then return end
    Anti.GamePaused.enabled = false
    if Anti.GamePaused.childAdded then Anti.GamePaused.childAdded:Disconnect(); Anti.GamePaused.childAdded = nil end
    if Anti.GamePaused.propConn then Anti.GamePaused.propConn:Disconnect(); Anti.GamePaused.propConn = nil end
    if Anti.GamePaused.loopConn then Anti.GamePaused.loopConn:Disconnect(); Anti.GamePaused.loopConn = nil end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-GameplayPaused disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 4. ADVANCED ANTI-AFK V2 (Idled Signal + VirtualUser + VirtualInputManager)
-- ═══════════════════════════════════════════════════════════════════════════════
local function afkPulse()
    pcall(function()
        local vu = game:GetService("VirtualUser")
        vu:CaptureController()
        vu:ClickButton2(Vector2.zero, workspace.CurrentCamera and workspace.CurrentCamera.CFrame or CFrame.new())
    end)
    pcall(function()
        local vim = game:GetService("VirtualInputManager")
        vim:SendMouseMoveEvent(1, 1, game)
    end)
end

afkStart = function()
    if Anti.AFK.enabled then return end
    Anti.AFK.enabled = true
    pcall(function()
        if getconnections then
            for _, c in ipairs(getconnections(LP.Idled)) do
                pcall(function() c:Disable() end)
                pcall(function() c:Disconnect() end)
            end
        end
    end)
    if Anti.AFK.conn then Anti.AFK.conn:Disconnect() end
    Anti.AFK.conn = LP.Idled:Connect(function()
        if not Anti.AFK.enabled then return end
        afkPulse()
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-AFK v2 (Multi-Hook) ON")
    sToggleOn()
end

afkStop = function()
    if not Anti.AFK.enabled then return end
    Anti.AFK.enabled = false
    if Anti.AFK.conn then Anti.AFK.conn:Disconnect(); Anti.AFK.conn = nil end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-AFK disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- ═══════════════════════════════════════════════════════════════════════════════
-- 5. VC BYPASS (Original Activation/Mic Logic + Standalone Custom GUI)
--    • Replaces previous Coco Anti-VC with the exact logic & GUI from vc_original_logic_custom_gui.lua
--    • Requires executor getconnections; clones CoreGui toggle_mic_mute and hooks IconHitArea_toggle_mic_mute
-- ═══════════════════════════════════════════════════════════════════════════════
local vcDisabledConns = {}
local vcStoredFolder = nil

local function vcNotify(t)
    print("[VC Bypass] " .. tostring(t))
    pcall(function()
        StarterGui:SetCore("SendNotification", {
            Title = "VC Bypass",
            Text = tostring(t),
            Duration = 5,
        })
    end)
end

local function updateVCBypassUI(statusText, statusColor, buttonText)
    if statusText then
        Anti.VC.statusText = statusText
        if Anti.VC.statusLbl and Anti.VC.statusLbl.Parent then
            Anti.VC.statusLbl.Text = statusText
        end
        if Anti.VC.rowSubLbl and Anti.VC.rowSubLbl.Parent then
            Anti.VC.rowSubLbl.Text = statusText
        end
    end
    if statusColor and Anti.VC.statusLbl and Anti.VC.statusLbl.Parent then
        Anti.VC.statusLbl.TextColor3 = statusColor
    end
    if buttonText and Anti.VC.activateBtn and Anti.VC.activateBtn.Parent then
        Anti.VC.activateBtn.Text = buttonText
    end
end

vcStart = function()
    if Anti.VC.running or Anti.VC.enabled then
        vcNotify(Anti.VC.enabled and "Already active" or "Already running")
        return
    end
    Anti.VC.running = true
    updateVCBypassUI("Status: Waiting for unmute...", Color3.new(1, 1, 1), "WORKING...")
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end

    task.spawn(function()
        local ok, err = pcall(function()
            -- Original feature logic below, with original CoreGui mic clone and its own hit area.
            local cloneref_ = cloneref or function(x) return x end
            local clonefunction_ = clonefunction or function(x) return x end
            local voice = cloneref_(game:GetService("VoiceChatService"))
            local internal = cloneref_(game:GetService("VoiceChatInternal"))
            local callback = clonefunction_(getconnections)
            local folder = Instance.new("Folder", game:GetService("RobloxReplicatedStorage"))
            vcStoredFolder = folder
            local originalParent = nil
            local originalMic = nil
            local coreGui = CoreGui or game:GetService("CoreGui")
            pcall(function()
                for _, descendant in ipairs(coreGui:GetDescendants()) do
                    if descendant.Name == "toggle_mic_mute" then
                        originalMic = descendant
                        originalParent = descendant.Parent
                        break
                    end
                end
            end)
            local function getIcon(arg)
                return (arg or originalMic):WaitForChild("IntegrationIconFrame", 15):WaitForChild("IntegrationIcon", 15)["1"]
            end
            local function isPaused() return internal:IsPublishPaused() end
            local function setPaused(value) internal:PublishPause(value) end
            if not originalMic then
                voice:joinVoice()
                pcall(function()
                    if originalParent then
                        originalMic = originalParent:WaitForChild("toggle_mic_mute", 15)
                    else
                        for _, descendant in ipairs(coreGui:GetDescendants()) do
                            if descendant.Name == "toggle_mic_mute" then
                                originalMic = descendant
                                originalParent = descendant.Parent
                                break
                            end
                        end
                    end
                end)
                if not originalMic then error("Mic button not found") end
            end
            vcNotify("Unmute your mic to continue")
            repeat
                task.wait(2)
            until getIcon().Image ~= "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
            voice:leaveVoice()
            task.wait(2)
            local connections = callback(internal.StateChanged)
            vcDisabledConns = {}
            for i = 7, #connections do
                if connections[i] then
                    connections[i]:Disable()
                    table.insert(vcDisabledConns, connections[i])
                end
            end
            task.wait(2)
            voice:joinVoice()
            pcall(function()
                if originalParent then originalMic = originalParent:WaitForChild("toggle_mic_mute", 15) end
            end)
            if originalMic and originalParent then
                local clonedMic = originalMic:Clone()
                originalMic.Parent = folder
                clonedMic.Name = "toggle_mic_mute_new"
                clonedMic.Parent = originalParent
                local clonedIcon = getIcon(clonedMic)
                local originalIcon = getIcon(originalMic)
                setPaused(true)
                clonedIcon.Image = "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
                clonedMic:WaitForChild("IconHitArea_toggle_mic_mute", 15).Activated:Connect(function()
                    -- Same original handler: click cloned Roblox mic icon to toggle.
                    local paused = not isPaused()
                    setPaused(paused)
                    if paused then
                        clonedIcon.Image = "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
                    else
                        clonedIcon.Image = originalIcon.Image
                    end
                end)
            end
        end)
        Anti.VC.running = false
        if ok then
            Anti.VC.enabled = true
            updateVCBypassUI("Status: Active", Color3.fromRGB(102, 235, 150), "ANTI VC ACTIVE")
            if syncAllAntiButtons then pcall(syncAllAntiButtons) end
            vcNotify("Sequence completed. Toggle mic using the cloned Roblox mic icon.")
        else
            Anti.VC.enabled = false
            updateVCBypassUI("Status: Failed", Color3.fromRGB(255, 118, 118), "RETRY")
            if syncAllAntiButtons then pcall(syncAllAntiButtons) end
            vcNotify("Error: " .. tostring(err))
        end
    end)
end

vcStop = function()
    if not Anti.VC.enabled and not Anti.VC.running then return end
    Anti.VC.running = false
    Anti.VC.enabled = false
    for i = #vcDisabledConns, 1, -1 do
        local c = vcDisabledConns[i]
        if c then pcall(function() c:Enable() end) end
        vcDisabledConns[i] = nil
    end
    pcall(function()
        local coreGui = CoreGui or game:GetService("CoreGui")
        if vcStoredFolder and vcStoredFolder.Parent then
            local origMic = vcStoredFolder:FindFirstChild("toggle_mic_mute")
            if coreGui then
                for _, v in ipairs(coreGui:GetDescendants()) do
                    if v.Name == "toggle_mic_mute_new" and v.Parent then
                        if origMic then origMic.Parent = v.Parent end
                        v:Destroy()
                        break
                    end
                end
            end
            vcStoredFolder:Destroy()
            vcStoredFolder = nil
        end
    end)
    updateVCBypassUI("Status: Not active", Color3.new(1, 1, 1), "Activate VC Bypass")
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    vcNotify("VC Bypass reset")
end

local function openStandaloneOriginalVCGUI()
    local host
    if type(gethui) == "function" then
        local ok, value = pcall(gethui)
        if ok and typeof(value) == "Instance" then host = value end
    end
    host = host or CoreGui or (LP and LP:FindFirstChildOfClass("PlayerGui"))
    if not host then return end

    local previous = host:FindFirstChild("StandaloneOriginalVCGUI")
    if previous then
        previous:Destroy()
        return
    end

    local vcGui = Instance.new("ScreenGui")
    vcGui.Name = "StandaloneOriginalVCGUI"
    vcGui.ResetOnSpawn = false
    vcGui.IgnoreGuiInset = true
    vcGui.DisplayOrder = 999999
    pcall(function() if syn and syn.protect_gui then syn.protect_gui(vcGui) end end)
    vcGui.Parent = host

    local function make(class, parent, props)
        local o = Instance.new(class)
        for k, v in pairs(props) do o[k] = v end
        o.Parent = parent
        return o
    end

    local panel = make("Frame", vcGui, {
        Size = UDim2.fromOffset(320, 155),
        Position = UDim2.new(0.5, -160, 0.35, 0),
        BackgroundColor3 = Color3.fromRGB(29, 31, 41),
        BorderSizePixel = 0,
        Active = true,
        Draggable = true,
    })
    make("UICorner", panel, { CornerRadius = UDim.new(0, 10) })

    make("TextLabel", panel, {
        Size = UDim2.new(1, -55, 0, 34),
        Position = UDim2.fromOffset(12, 6),
        Text = "VC BYPASS",
        TextColor3 = Color3.new(1, 1, 1),
        BackgroundTransparency = 1,
        TextXAlignment = Enum.TextXAlignment.Left,
        Font = Enum.Font.GothamBold,
        TextSize = 17,
    })

    local close = make("TextButton", panel, {
        Size = UDim2.fromOffset(30, 28),
        Position = UDim2.new(1, -37, 0, 8),
        Text = "X",
        BackgroundColor3 = Color3.fromRGB(146, 54, 67),
        TextColor3 = Color3.new(1, 1, 1),
        Font = Enum.Font.GothamBold,
    })

    local status = make("TextLabel", panel, {
        Size = UDim2.new(1, -24, 0, 35),
        Position = UDim2.fromOffset(12, 44),
        Text = Anti.VC.enabled and "Status: Active" or (Anti.VC.running and "Status: Waiting for unmute..." or "Status: Not active"),
        TextColor3 = Anti.VC.enabled and Color3.fromRGB(102, 235, 150) or Color3.new(1, 1, 1),
        BackgroundColor3 = Color3.fromRGB(43, 46, 58),
        Font = Enum.Font.Gotham,
        TextSize = 14,
    })

    local button = make("TextButton", panel, {
        Size = UDim2.new(1, -24, 0, 43),
        Position = UDim2.fromOffset(12, 91),
        Text = Anti.VC.enabled and "ANTI VC ACTIVE" or (Anti.VC.running and "WORKING..." or "Activate VC Bypass"),
        TextColor3 = Color3.new(1, 1, 1),
        BackgroundColor3 = Color3.fromRGB(61, 109, 207),
        Font = Enum.Font.GothamBold,
        TextSize = 15,
    })

    for _, b in ipairs({ close, status, button }) do
        make("UICorner", b, { CornerRadius = UDim.new(0, 6) })
    end

    Anti.VC.statusLbl = status
    Anti.VC.activateBtn = button

    close.MouseButton1Click:Connect(function()
        vcGui:Destroy()
    end)

    button.MouseButton1Click:Connect(function()
        vcStart()
    end)

    vcNotify("GUI loaded")
end

_G.ActivateCocoAntiVC = vcStart
_G.ActivateTeslaAntiVC = vcStart
Anti.VC.openPanelFn = openStandaloneOriginalVCGUI
Anti.VC.openCompactPanelFn = openStandaloneOriginalVCGUI

-- ═══════════════════════════════════════════════════════════════════════════════
-- 5B. NOVOLINE V3 DUAL ANTI-VC BYPASSER SUITE (BOTH V1 & V2 MODES + GLASS UI)
--     • Preserves Original VC Bypass above AND adds both Novoline V3 Anti-VC modes:
--       - Bypass V1: leaveVoice -> disable all VoiceChatInternal.StateChanged conns
--                    -> joinVoice -> PublishPause(true) + Floating Glass NV_MicToggleGUI
--       - Bypass V2: Unmute wait -> leaveVoice -> disable StateChanged[7..#conns]
--                    -> joinVoice -> TopBar CustomVoiceController + RedVoiceDot sync
-- ═══════════════════════════════════════════════════════════════════════════════
do
    local nvCloneref = cloneref or function(x) return x end
    local nvClonefunction = clonefunction or function(x) return x end
    local nvGetconnections = (type(getconnections) == "function" and nvClonefunction(getconnections)) or nil

    local nvV1DisabledConns = {}
    local nvV2DisabledConns = {}
    local nvV2RenderConn = nil
    local nvV2StoredFolder = nil
    local nvActivePanelStatusUpdater = nil

    local function nvGetGuiParent()
        if type(gethui) == "function" then
            local ok, res = pcall(gethui)
            if ok and typeof(res) == "Instance" then return res end
        end
        return CoreGui or (LP and LP:FindFirstChildOfClass("PlayerGui"))
    end

    local function nvUpdateStatus(modeTag, text, color)
        if modeTag == "V1" then
            Anti.VCV1.statusText = text
            if Anti.VCV1.rowSubLbl and Anti.VCV1.rowSubLbl.Parent then
                Anti.VCV1.rowSubLbl.Text = text
            end
        elseif modeTag == "V2" then
            Anti.VCV2.statusText = text
            if Anti.VCV2.rowSubLbl and Anti.VCV2.rowSubLbl.Parent then
                Anti.VCV2.rowSubLbl.Text = text
            end
        end
        if nvActivePanelStatusUpdater then
            pcall(nvActivePanelStatusUpdater, text, color)
        end
        if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    end

    local function nvMakeDraggable(frame, dragHandle)
        local dragging, dragInput, dragStart, startPos
        dragHandle = dragHandle or frame
        dragHandle.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = frame.Position
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        dragging = false
                    end
                end)
            end
        end)
        dragHandle.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                dragInput = input
            end
        end)
        UIS.InputChanged:Connect(function(input)
            if input == dragInput and dragging then
                local delta = input.Position - dragStart
                TweenService:Create(frame, TweenInfo.new(0.08, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
                    Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
                }):Play()
            end
        end)
    end

    local function nvSpawnV1FloatingMicGUI(vci)
        local parent = nvGetGuiParent()
        if not parent then return end
        local oldGui = parent:FindFirstChild("NV_MicToggleGUI")
        if oldGui then oldGui:Destroy() end

        local micGui = Instance.new("ScreenGui")
        micGui.Name = "NV_MicToggleGUI"
        micGui.ResetOnSpawn = false
        micGui.DisplayOrder = 999999
        pcall(function() if syn and syn.protect_gui then syn.protect_gui(micGui) end end)
        micGui.Parent = parent

        local container = Instance.new("Frame")
        container.Size = UDim2.new(0, 75, 0, 75)
        container.Position = UDim2.new(0.85, 0, 0.4, 0)
        container.BackgroundColor3 = Color3.fromRGB(16, 12, 24)
        container.BackgroundTransparency = 0.28
        container.BorderSizePixel = 0
        container.Active = true
        container.Parent = micGui
        Instance.new("UICorner", container).CornerRadius = UDim.new(0, 18)

        local grad = Instance.new("UIGradient")
        grad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(200, 190, 230)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(130, 115, 160)),
        })
        grad.Rotation = 45
        grad.Parent = container

        local stroke = Instance.new("UIStroke")
        stroke.Color = Color3.fromRGB(239, 68, 68)
        stroke.Thickness = 2
        stroke.Transparency = 0.2
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = container

        local iconLbl = Instance.new("TextLabel")
        iconLbl.Size = UDim2.new(1, 0, 0, 40)
        iconLbl.Position = UDim2.new(0, 0, 0, 10)
        iconLbl.BackgroundTransparency = 1
        iconLbl.Text = "🔇"
        iconLbl.TextSize = 26
        iconLbl.Font = Enum.Font.GothamBold
        iconLbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        iconLbl.Parent = container

        local stateLbl = Instance.new("TextLabel")
        stateLbl.Size = UDim2.new(1, 0, 0, 15)
        stateLbl.Position = UDim2.new(0, 0, 1, -20)
        stateLbl.BackgroundTransparency = 1
        stateLbl.Text = "MUTED"
        stateLbl.TextSize = 10
        stateLbl.Font = Enum.Font.GothamBold
        stateLbl.TextColor3 = Color3.fromRGB(239, 68, 68)
        stateLbl.Parent = container

        local hitBtn = Instance.new("TextButton")
        hitBtn.Size = UDim2.new(1, 0, 1, 0)
        hitBtn.BackgroundTransparency = 1
        hitBtn.Text = ""
        hitBtn.Parent = container

        nvMakeDraggable(container, hitBtn)

        local function syncV1MicVisual(isMutedNow)
            Anti.VCV1.muted = isMutedNow
            if not isMutedNow then
                iconLbl.Text = "🎙️"
                stateLbl.Text = "UNMUTED"
                stateLbl.TextColor3 = Color3.fromRGB(16, 185, 129)
                TweenService:Create(stroke, TweenInfo.new(0.2), { Color = Color3.fromRGB(16, 185, 129) }):Play()
                TweenService:Create(container, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(16, 45, 35) }):Play()
            else
                iconLbl.Text = "🔇"
                stateLbl.Text = "MUTED"
                stateLbl.TextColor3 = Color3.fromRGB(239, 68, 68)
                TweenService:Create(stroke, TweenInfo.new(0.2), { Color = Color3.fromRGB(239, 68, 68) }):Play()
                TweenService:Create(container, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(16, 12, 24) }):Play()
            end
        end

        hitBtn.MouseButton1Click:Connect(function()
            local okP, curPaused = pcall(function() return vci:IsPublishPaused() end)
            local nextMuted = okP and (not curPaused) or (not Anti.VCV1.muted)
            pcall(function() vci:PublishPause(nextMuted) end)
            syncV1MicVisual(nextMuted)
            nvUpdateStatus("V1", "Status: V1 Active (" .. (nextMuted and "Muted" or "Unmuted") .. ")", Color3.fromRGB(16, 185, 129))
        end)
    end

    local function nvCleanupV1()
        for i = #nvV1DisabledConns, 1, -1 do
            local c = nvV1DisabledConns[i]
            if c then pcall(function() c:Enable() end) end
            nvV1DisabledConns[i] = nil
        end
        local parent = nvGetGuiParent()
        if parent then
            local g = parent:FindFirstChild("NV_MicToggleGUI")
            if g then pcall(function() g:Destroy() end) end
        end
        Anti.VCV1.enabled = false
        Anti.VCV1.running = false
        nvUpdateStatus("V1", "Status: Idle (V1 Disabled)", Color3.fromRGB(165, 155, 185))
    end

    local function nvCleanupV2()
        if nvV2RenderConn then
            pcall(function() nvV2RenderConn:Disconnect() end)
            nvV2RenderConn = nil
        end
        for i = #nvV2DisabledConns, 1, -1 do
            local c = nvV2DisabledConns[i]
            if c then pcall(function() c:Enable() end) end
            nvV2DisabledConns[i] = nil
        end
        pcall(function()
            local cg = nvCloneref(game:GetService("CoreGui"))
            for _, d in ipairs(cg:GetDescendants()) do
                if d.Name == "toggle_mic_mute" and d:IsA("GuiObject") then
                    d.Visible = true
                end
            end
            local parent = nvGetGuiParent()
            if parent and parent:FindFirstChild("CustomVoiceController") then
                parent.CustomVoiceController:Destroy()
            end
            if cg:FindFirstChild("CustomVoiceController") then
                cg.CustomVoiceController:Destroy()
            end
            if nvV2StoredFolder and nvV2StoredFolder.Parent then
                nvV2StoredFolder:Destroy()
                nvV2StoredFolder = nil
            end
        end)
        Anti.VCV2.enabled = false
        Anti.VCV2.running = false
        nvUpdateStatus("V2", "Status: Idle (V2 Disabled)", Color3.fromRGB(165, 155, 185))
    end

    local function nvStartV1()
        if Anti.VCV1.running then return end
        nvCleanupV1()
        Anti.VCV1.running = true
        nvUpdateStatus("V1", "Status: Starting V1 Bypass...", Color3.fromRGB(245, 158, 11))

        task.spawn(function()
            local ok, err = pcall(function()
                local vcs = nvCloneref(game:GetService("VoiceChatService"))
                local vci = nvCloneref(game:GetService("VoiceChatInternal"))
                nvUpdateStatus("V1", "Status: Leaving Voice...", Color3.fromRGB(245, 158, 11))
                vcs:leaveVoice()
                task.wait(0.3)

                nvUpdateStatus("V1", "Status: Disabling StateChanged Conns...", Color3.fromRGB(245, 158, 11))
                if nvGetconnections then
                    for _, conn in ipairs(nvGetconnections(vci.StateChanged)) do
                        pcall(function()
                            conn:Disable()
                            table.insert(nvV1DisabledConns, conn)
                        end)
                    end
                end
                task.wait(0.2)

                nvUpdateStatus("V1", "Status: Rejoining Voice...", Color3.fromRGB(245, 158, 11))
                vcs:joinVoice()
                task.wait(0.5)
                pcall(function() vci:PublishPause(true) end)
                Anti.VCV1.muted = true
                nvSpawnV1FloatingMicGUI(vci)
            end)
            Anti.VCV1.running = false
            if ok then
                Anti.VCV1.enabled = true
                nvUpdateStatus("V1", "Status: V1 Bypassed! Use Floating UI", Color3.fromRGB(16, 185, 129))
                notify("NOVOLINE ANTI-VC V1", "V1 Bypass active! Use the floating glass mic button to mute/unmute.")
                sToggleOn()
            else
                Anti.VCV1.enabled = false
                nvUpdateStatus("V1", "Status: V1 Failed (" .. tostring(err):sub(1, 36) .. ")", Color3.fromRGB(239, 68, 68))
                notify("NOVOLINE ANTI-VC V1", "V1 Error: " .. tostring(err))
                sError()
            end
        end)
    end

    local function nvStartV2()
        if Anti.VCV2.running then return end
        nvCleanupV2()
        Anti.VCV2.running = true
        nvUpdateStatus("V2", "Status: Scanning CoreGui for Mic...", Color3.fromRGB(245, 158, 11))

        task.spawn(function()
            local ok, err = pcall(function()
                if not nvGetconnections then
                    error("Executor missing getconnections")
                end
                local vcs = nvCloneref(game:GetService("VoiceChatService"))
                local vci = nvCloneref(game:GetService("VoiceChatInternal"))
                local cg = nvCloneref(game:GetService("CoreGui"))
                local rrs = nvCloneref(game:GetService("RobloxReplicatedStorage"))

                local folder = Instance.new("Folder")
                folder.Name = "NV_VCB2_Folder"
                folder.Parent = rrs
                nvV2StoredFolder = folder

                local originalMic, originalParent
                for _, d in ipairs(cg:GetDescendants()) do
                    if d.Name == "toggle_mic_mute" then
                        originalMic = d
                        originalParent = d.Parent
                        break
                    end
                end

                local function getMicIcon(btn)
                    local target = btn or originalMic
                    if not target then return nil end
                    local f1 = target:WaitForChild("IntegrationIconFrame", 5)
                    if not f1 then return nil end
                    local f2 = f1:WaitForChild("IntegrationIcon", 5)
                    if not f2 then return nil end
                    return f2:WaitForChild("1", 5)
                end

                if not originalMic then
                    nvUpdateStatus("V2", "Status: Joining VC to find Mic...", Color3.fromRGB(245, 158, 11))
                    pcall(function() vcs:joinVoice() end)
                    local t0 = tick()
                    repeat
                        for _, d in ipairs(cg:GetDescendants()) do
                            if d.Name == "toggle_mic_mute" then
                                originalMic = d
                                originalParent = d.Parent
                                break
                            end
                        end
                        task.wait(0.5)
                    until originalMic or (tick() - t0 > 10)
                    if not originalMic then
                        error("Mic button not found in CoreGui")
                    end
                end

                local micIcon = getMicIcon(originalMic)
                if not micIcon then
                    error("Mic icon structure unsupported")
                end

                nvUpdateStatus("V2", "Status: Unmute your Roblox Mic to continue!", Color3.fromRGB(59, 130, 246))
                vcNotify("Unmute your mic inside Roblox to continue V2!")
                repeat
                    task.wait(0.5)
                until not Anti.VCV2.running or micIcon.Image ~= "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
                if not Anti.VCV2.running then error("Cancelled") end

                nvUpdateStatus("V2", "Status: Leaving Voice...", Color3.fromRGB(245, 158, 11))
                vcs:leaveVoice()
                task.wait(1.5)

                nvUpdateStatus("V2", "Status: Disabling StateChanged[7+]...", Color3.fromRGB(245, 158, 11))
                local conns = nvGetconnections(vci.StateChanged)
                for i = 7, #conns do
                    if conns[i] then
                        pcall(function()
                            conns[i]:Disable()
                            table.insert(nvV2DisabledConns, conns[i])
                        end)
                    end
                end
                task.wait(1.5)

                nvUpdateStatus("V2", "Status: Rejoining & Hooking TopBar...", Color3.fromRGB(245, 158, 11))
                vcs:joinVoice()
                if originalParent then
                    originalMic = originalParent:WaitForChild("toggle_mic_mute", 10)
                end
                if originalMic and originalParent then
                    local clonedMic = originalMic:Clone()
                    clonedMic.Parent = folder
                    originalMic.Visible = false

                    local guiHost = nvGetGuiParent() or cg
                    if guiHost:FindFirstChild("CustomVoiceController") then
                        guiHost.CustomVoiceController:Destroy()
                    end

                    local customGui = Instance.new("ScreenGui")
                    customGui.Name = "CustomVoiceController"
                    customGui.DisplayOrder = 999999
                    customGui.IgnoreGuiInset = true
                    customGui.ResetOnSpawn = false
                    pcall(function() if syn and syn.protect_gui then syn.protect_gui(customGui) end end)
                    customGui.Parent = guiHost

                    local fakeBtn = Instance.new("ImageButton")
                    fakeBtn.Name = "FakeMicButton"
                    fakeBtn.BackgroundTransparency = 1
                    fakeBtn.Image = ""
                    local absPos = originalMic.AbsolutePosition
                    local absSize = originalMic.AbsoluteSize
                    local topbarInset = game:GetService("GuiService"):GetGuiInset()
                    fakeBtn.Position = UDim2.fromOffset(absPos.X, absPos.Y + topbarInset.Y)
                    fakeBtn.Size = UDim2.fromOffset(absSize.X, absSize.Y)
                    fakeBtn.Parent = customGui

                    clonedMic.Visible = true
                    clonedMic.Position = UDim2.fromOffset(0, 0)
                    clonedMic.Size = UDim2.fromScale(1, 1)
                    clonedMic.Parent = fakeBtn

                    local clonedHit = clonedMic:FindFirstChild("IconHitArea_toggle_mic_mute", true)
                    if clonedHit then clonedHit.Active = false end

                    local clonedIcon = getMicIcon(clonedMic)
                    local originalIcon = getMicIcon(originalMic)
                    local redDot = clonedMic:FindFirstChild("RedVoiceDot", true)

                    local v2IsMuted = true
                    Anti.VCV2.muted = true
                    pcall(function() vci:PublishPause(true) end)
                    if clonedIcon then
                        clonedIcon.Image = "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
                    end
                    if redDot then
                        redDot.Visible = false
                    end

                    fakeBtn.MouseButton1Click:Connect(function()
                        v2IsMuted = not v2IsMuted
                        Anti.VCV2.muted = v2IsMuted
                        pcall(function() vci:PublishPause(v2IsMuted) end)
                        if v2IsMuted and clonedIcon then
                            clonedIcon.Image = "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png"
                        end
                        nvUpdateStatus("V2", "Status: V2 Active (" .. (v2IsMuted and "Muted" or "Unmuted") .. ")", Color3.fromRGB(16, 185, 129))
                    end)

                    nvV2RenderConn = RunService.RenderStepped:Connect(function()
                        if originalMic and originalMic.Parent then
                            local pNow = originalMic.AbsolutePosition
                            local insetNow = game:GetService("GuiService"):GetGuiInset()
                            fakeBtn.Position = UDim2.fromOffset(pNow.X, pNow.Y + insetNow.Y)
                        end
                        if redDot then
                            redDot.Visible = not v2IsMuted
                        end
                        if not v2IsMuted and clonedIcon and originalIcon then
                            if originalIcon.Image == "rbxasset://textures/ui/VoiceChat/MicLight/Muted.png" then
                                clonedIcon.Image = "rbxasset://textures/ui/VoiceChat/MicLight/Unmuted0.png"
                            else
                                clonedIcon.Image = originalIcon.Image
                            end
                        end
                    end)
                else
                    error("Failed to re-hook TopBar mic after rejoin")
                end
            end)
            Anti.VCV2.running = false
            if ok then
                Anti.VCV2.enabled = true
                nvUpdateStatus("V2", "Status: V2 Bypassed! Topbar Ready", Color3.fromRGB(16, 185, 129))
                vcNotify("Bypass V2 Complete! Use the normal Topbar Mic Icon.")
                sToggleOn()
            else
                Anti.VCV2.enabled = false
                if tostring(err):find("Cancelled") then
                    nvUpdateStatus("V2", "Status: V2 Cancelled", Color3.fromRGB(165, 155, 185))
                else
                    nvUpdateStatus("V2", "Status: V2 Failed (" .. tostring(err):sub(1, 34) .. ")", Color3.fromRGB(239, 68, 68))
                    vcNotify("V2 Error: " .. tostring(err))
                    sError()
                end
            end
        end)
    end

    local function nvToggleMuteAny()
        local ok, newMuted = pcall(function()
            local vci = nvCloneref(game:GetService("VoiceChatInternal"))
            local nextState = not vci:IsPublishPaused()
            vci:PublishPause(nextState)
            return nextState
        end)
        if ok then
            Anti.VCV1.muted = newMuted
            Anti.VCV2.muted = newMuted
            notify("🎙️ VC PUBLISH PAUSE", newMuted and "Microphone Muted (PublishPause = true)" or "Microphone Unmuted (PublishPause = false)")
            return newMuted
        end
        return nil
    end

    local function launchNovolineVCBypasser(defaultMode)
        local parent = nvGetGuiParent()
        if not parent then return end

        local existing = parent:FindFirstChild("NV_VCBypasser")
        if existing then
            existing:Destroy()
            nvActivePanelStatusUpdater = nil
