-- ═══════════════════════════════════════════════════════════════════════════════
-- 13. ADVANCED ANTI-SEAT / COUCH-KIDNAP & VEHICLESEAT DESTROYER V3
--     • Neutralizes map Seats, VehicleSeats, Couch tools, ShoppingCarts & Stretchers
--       so trolls can never force-sit your character and teleport you into the void!
-- ═══════════════════════════════════════════════════════════════════════════════
local function neutralizeSeatInstance(seat)
    if not seat or (not seat:IsA("Seat") and not seat:IsA("VehicleSeat")) then return end
    if not Anti.SeatTrap.savedSeats[seat] then
        Anti.SeatTrap.savedSeats[seat] = {
            Disabled = seat.Disabled,
            CanTouch = seat.CanTouch,
        }
        Anti.SeatTrap.neutralizedSeats = (Anti.SeatTrap.neutralizedSeats or 0) + 1
    end
    pcall(function()
        seat.Disabled = true
        seat.CanTouch = false
        local sw = seat:FindFirstChild("SeatWeld") or seat:FindFirstChildOfClass("Weld")
        if sw then sw:Destroy() end
    end)
end

local function enforceAntiSitOnHumanoid(hum)
    if not hum or not hum.Parent then return end
    pcall(function()
        hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
        if hum.Sit then hum.Sit = false end
        if hum:GetState() == Enum.HumanoidStateType.Seated then
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end
    end)
end

local function hookAntiSitCharacter(ch)
    if not ch then return end
    if Anti.SeatTrap.charConns then
        for _, c in ipairs(Anti.SeatTrap.charConns) do pcall(function() c:Disconnect() end) end
    end
    Anti.SeatTrap.charConns = {}
    local function bindHum(hum)
        if not hum then return end
        enforceAntiSitOnHumanoid(hum)
        table.insert(Anti.SeatTrap.charConns, hum:GetPropertyChangedSignal("Sit"):Connect(function()
            if Anti.SeatTrap.enabled and hum.Sit then
                enforceAntiSitOnHumanoid(hum)
            end
        end))
        table.insert(Anti.SeatTrap.charConns, hum.StateChanged:Connect(function(_, newState)
            if Anti.SeatTrap.enabled and newState == Enum.HumanoidStateType.Seated then
                enforceAntiSitOnHumanoid(hum)
            end
        end))
    end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if hum then bindHum(hum) end
    table.insert(Anti.SeatTrap.charConns, ch.ChildAdded:Connect(function(child)
        if child:IsA("Humanoid") then bindHum(child) end
    end))
    table.insert(Anti.SeatTrap.charConns, ch.DescendantAdded:Connect(function(obj)
        if not Anti.SeatTrap.enabled then return end
        if obj:IsA("SeatWeld") or obj.Name == "SeatWeld" then
            pcall(function() obj:Destroy() end)
        end
    end))
end

Anti.SeatTrap.startFn = function(silent)
    if Anti.SeatTrap.enabled and Anti.SeatTrap.loopConn and Anti.SeatTrap.wsDescConn then
        if syncAllAntiButtons then pcall(syncAllAntiButtons) end
        return
    end
    Anti.SeatTrap.enabled = true
    task.spawn(function()
        pcall(function()
            local list = workspace:GetDescendants()
            for idx, obj in ipairs(list) do
                if not Anti.SeatTrap.enabled then break end
                if obj:IsA("Seat") or obj:IsA("VehicleSeat") then
                    neutralizeSeatInstance(obj)
                elseif (obj:IsA("SeatWeld") or obj.Name == "SeatWeld") and LP.Character then
                    local p0, p1 = obj.Part0, obj.Part1
                    if (p0 and p0:IsDescendantOf(LP.Character)) or (p1 and p1:IsDescendantOf(LP.Character)) then
                        pcall(function() obj:Destroy() end)
                    end
                end
                if idx % 800 == 0 then
                    RunService.Heartbeat:Wait()
                end
            end
        end)
    end)
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Character then
            for _, obj in ipairs(p.Character:GetDescendants()) do
                if obj:IsA("Seat") or obj:IsA("VehicleSeat") then
                    neutralizeSeatInstance(obj)
                end
            end
        end
    end
    hookAntiSitCharacter(LP.Character)
    if Anti.SeatTrap.charAddedConn then Anti.SeatTrap.charAddedConn:Disconnect() end
    Anti.SeatTrap.charAddedConn = LP.CharacterAdded:Connect(function(ch)
        if not Anti.SeatTrap.enabled then return end
        task.defer(function()
            if Anti.SeatTrap.enabled then hookAntiSitCharacter(ch) end
        end)
    end)
    if Anti.SeatTrap.wsDescConn then Anti.SeatTrap.wsDescConn:Disconnect() end
    Anti.SeatTrap.wsDescConn = workspace.DescendantAdded:Connect(function(obj)
        if not Anti.SeatTrap.enabled then return end
        if obj:IsA("Seat") or obj:IsA("VehicleSeat") then
            neutralizeSeatInstance(obj)
        elseif (obj:IsA("SeatWeld") or obj.Name == "SeatWeld") and LP.Character then
            local p0, p1 = obj.Part0, obj.Part1
            if (p0 and p0:IsDescendantOf(LP.Character)) or (p1 and p1:IsDescendantOf(LP.Character)) then
                pcall(function() obj:Destroy() end)
            end
        end
    end)
    if Anti.SeatTrap.loopConn then Anti.SeatTrap.loopConn:Disconnect() end
    Anti.SeatTrap.loopConn = RunService.Stepped:Connect(function()
        if not Anti.SeatTrap.enabled then return end
        local ch = LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function()
                if hum:GetStateEnabled(Enum.HumanoidStateType.Seated) then
                    hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                end
                if hum.Sit then
                    hum.Sit = false
                end
            end)
        end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
    if not silent then
        notify("COCO POWDER", "Anti-Sit / Couch-Kidnap Destroyer (Always-On) ON")
        sToggleOn()
    end
end

Anti.SeatTrap.stopFn = function()
    if Anti.lockAlwaysOn then
        if not Anti.SeatTrap.enabled or not Anti.SeatTrap.loopConn or not Anti.SeatTrap.wsDescConn then
            Anti.SeatTrap.startFn(true)
        end
        if syncAllAntiButtons then pcall(syncAllAntiButtons) end
        if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
        notify("COCO POWDER", "Anti-Sit is locked as Always-On (unlock in Anti Shield tab to sit in vehicles)!")
        sToggleOn()
        return
    end
    Anti.SeatTrap.enabled = false
    if Anti.SeatTrap.loopConn then Anti.SeatTrap.loopConn:Disconnect(); Anti.SeatTrap.loopConn = nil end
    if Anti.SeatTrap.wsDescConn then Anti.SeatTrap.wsDescConn:Disconnect(); Anti.SeatTrap.wsDescConn = nil end
    if Anti.SeatTrap.charAddedConn then Anti.SeatTrap.charAddedConn:Disconnect(); Anti.SeatTrap.charAddedConn = nil end
    if Anti.SeatTrap.charConns then
        for _, c in ipairs(Anti.SeatTrap.charConns) do pcall(function() c:Disconnect() end) end
        Anti.SeatTrap.charConns = {}
    end
    for seat, orig in pairs(Anti.SeatTrap.savedSeats) do
        if seat and seat.Parent then
            pcall(function()
                seat.Disabled = orig.Disabled
                seat.CanTouch = orig.CanTouch
            end)
        end
        Anti.SeatTrap.savedSeats[seat] = nil
    end
    local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if myHum then
        pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.Seated, true) end)
    end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
    notify("COCO POWDER", "Anti-Seat disabled — you can now sit in chairs & vehicles!")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 14. ADVANCED ANTI-TOOL-GRAB / COUCH / CARRY / CUFFS DISARMER V3
--     • Strips CanTouch & CanCollide on foreign Tools held by nearby players so
--       Couch-claim, Stretcher, Handcuffs, Lasso, and FE Tool-Bring scripts fail!
-- ═══════════════════════════════════════════════════════════════════════════════
Anti.ToolGuard.startFn = function()
    if Anti.ToolGuard.enabled then return end
    Anti.ToolGuard.enabled = true
    if Anti.ToolGuard.loopConn then Anti.ToolGuard.loopConn:Disconnect() end
    local lastToolScan = 0
    Anti.ToolGuard.loopConn = RunService.Heartbeat:Connect(function()
        if not Anti.ToolGuard.enabled then return end
        local now = tick()
        if now - lastToolScan < 0.14 then return end
        lastToolScan = now
        local myChar = LP.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return end
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local oRoot = p.Character:FindFirstChild("HumanoidRootPart")
                if not oRoot or (oRoot.Position - myRoot.Position).Magnitude < 42 then
