                        f0 = frames[cachedIdx]
                        f1 = frames[(cachedIdx == numFrames) and 1 or (cachedIdx + 1)]
                    elseif cachedIdx < numFrames and frames[cachedIdx + 1].time <= elapsed and (cachedIdx + 1 == numFrames or elapsed < frames[cachedIdx + 2].time) then
                        cachedIdx = cachedIdx + 1
