                        setPose("RightUpperArm", CFrame.Angles(math.rad(88) + pitch * 0.6, 0, math.rad(18)))
                        setPose("Left Arm", CFrame.Angles(math.rad(88) + pitch * 0.6, 0, math.rad(-18)))
