    local function encodeCocaUriComponent(s)
        return (tostring(s or ""):gsub("([^%w%-_%.!~%*'%(%)])", function(ch)
            return string.format("%%%02X", string.byte(ch))
        end))
    end

    local function ensureBuiltinReanimsMerged()
        local existing = {}
        for _, item in ipairs(allAnimations) do
            if item and item.name then existing[tostring(item.name)] = true end
        end
        for _, bName in ipairs(BUILTIN_REANIM_NAMES) do
            if not existing[bName] then
                table.insert(allAnimations, {
                    name = bName,
                    path = "builtin://" .. bName,
                    category = "Reanims",
                })
                existing[bName] = true
            end
        end
        for mName in MORTAL_MAIN_PACK:gmatch("([^|]+)") do
            if not existing[mName] then
                table.insert(allAnimations, {
                    name = mName,
                    path = MORTAL_MAIN_BASE .. encodeCocaUriComponent(mName) .. ".lua",
                    category = "Main",
                })
                existing[mName] = true
            end
        end
        for uName in MORTAL_UNICORNS_PACK:gmatch("([^|]+)") do
            if not existing[uName] then
                table.insert(allAnimations, {
                    name = uName,
                    path = MORTAL_UNICORNS_BASE .. encodeCocaUriComponent(uName) .. ".lua",
                    category = "Unicorns",
                })
                existing[uName] = true
            end
        end
        setSortedAnimations(allAnimations)
    end

    if #allAnimations == 0 then
        if type(isfile) == "function" and type(readfile) == "function" then
            local okExists, exists = pcall(isfile, ANIMS_CACHE_FILE)
            if okExists and exists then
                local okRead, rawJson = pcall(readfile, ANIMS_CACHE_FILE)
                if okRead then
                    loadCachedAnimsJson(rawJson)
                end
            end
        end
        ensureBuiltinReanimsMerged()
        mergeSavedCustomAnims()
        task.spawn(function()
            fetchGitHubAnimationsAsync()
            ensureBuiltinReanimsMerged()
            if type(populateList) == "function" then pcall(populateList) end
        end)
    else
        ensureBuiltinReanimsMerged()
    end

    -- Helper root.73.124.11: Load user config from angoorreanim.json
    if type(isfile) == "function" and type(readfile) == "function" then
        local okExists, exists = pcall(isfile, CONFIG_FILE)
        if okExists and exists then
            pcall(function()
                local raw = readfile(CONFIG_FILE)
                local decoded = HttpService:JSONDecode(raw)
                if type(decoded) == "table" then
                    if type(decoded.favs) == "table" then savedConfig.favs = decoded.favs end
                    if type(decoded.binds) == "table" then savedConfig.binds = decoded.binds end
                    if type(decoded.states) == "table" then savedConfig.states = decoded.states end
                    if decoded.speed then savedConfig.speed = tonumber(decoded.speed) or 1 end
                    if type(decoded.speedBinds) == "table" then savedConfig.speedBinds = decoded.speedBinds end
                    if type(decoded.customAnims) == "table" then savedConfig.customAnims = decoded.customAnims end
                    if type(decoded.hiddenLimbs) == "table" then savedConfig.hiddenLimbs = decoded.hiddenLimbs end
                end
            end)
        end
    end

    -- Always start with all body parts visible so stale config files never make the character invisible on launch
    _G.hiddenBodyParts = {}

    if type(savedConfig.customAnims) == "table" and #savedConfig.customAnims > 0 then
        mergeSavedCustomAnims()
    end

    -- Helper root.73.124.13: Global refresh hook _G._AngoorZenRefreshList
    _G._AngoorZenRefreshList = function()
        mergeSavedCustomAnims()
        if type(populateList) == "function" then
            pcall(populateList)
        end
    end

    -- Helper root.73.124.14: Save user config to angoorreanim.json
    local function saveConfig()
        if type(writefile) ~= "function" then return end
        pcall(function()
            writefile(CONFIG_FILE, HttpService:JSONEncode(savedConfig))
        end)
    end

    -- Helper root.73.124.15: Preload up to 12 favorite animations in background (only when reanimated)
    task.spawn(function()
        task.wait(4)
        if not zenApi or zenApi._isFallback or type(zenApi.preload_animation) ~= "function" then return end
        local okR, isR = pcall(zenApi.is_reanimated)
        if not okR or not isR then return end
        local favs = savedConfig.favs or {}
        local count = 0
        for favName, isFav in pairs(favs) do
            if isFav then
                if count >= 12 then break end
                for _, item in ipairs(allAnimations) do
                    if item.name == favName and type(item.path) == "string" and item.path:sub(1, 4) == "http" then
                        pcall(zenApi.preload_animation, item.path)
                        count = count + 1
                        task.wait(0.35)
                        break
                    end
                end
            end
        end
    end)

