            TweenService:Create(catCard, TweenInfo.new(0.2), { BackgroundTransparency = trans }):Play()
            TweenService:Create(mainCard, TweenInfo.new(0.2), { BackgroundTransparency = trans }):Play()
        end)

        createSwitchRow(prefGrp, 2, "Show Categories sidebar card", "Toggle between Dual-Card view and Single-Card view", UI.sidebarVisible, function(st)
            UI.sidebarVisible = st
            refreshDualLayout(true)
        end)

        createSwitchRow(prefGrp, 3, "UI sound effects (SFX)", "Play subtle tactile clicks & hover audio", UI.sfxEnabled, function(st)
            UI.sfxEnabled = st
        end)

        createSwitchRow(prefGrp, 4, "Live Cosmic Nebula Background", "Instant local purple energy clouds and drifting dust", UI.nebulaEnabled, function(st)
            setNebulaEnabled(st)
        end)

        local prefTagSw = createSwitchRow(prefGrp, 5, "Above Head Name Tags (ON / OFF)", "Small, sleek glowing badges over verified Coco Powder users", OwnerAdminState.overheadTagsEnabled, function(st)
            UI.setOverheadTagsEnabled(st, true)
        end)
        table.insert(UI.overheadTagSwitches, prefTagSw.setState)

        local prefSelfTagSw = createSwitchRow(prefGrp, 6, "Show My Own Above Tag (ON / OFF)", "Show or hide the overhead rank badge above your own head", OwnerAdminState.showSelfOverheadTag, function(st)
            UI.setSelfOverheadTagEnabled(st, true)
        end)
        table.insert(UI.selfOverheadTagSwitches, prefSelfTagSw.setState)

        UI.uiScale = UI.uiScale or 1.0
        local uiScaleSlider = createSliderInputRow(prefGrp, 7, "UI Window Scale (75% – 125%) (NEW)", "Resize the entire Dual-Card hub cleanly for PC or Mobile screens", 75, 125, math.floor((UI.uiScale or 1.0) * 100), 0, "%", function(pct)
            UI.uiScale = math.clamp(pct / 100, 0.75, 1.25)
            if UI.applyRootScaleFn then UI.applyRootScaleFn(UI.uiScale) end
            if UI.autoSaveConfig and UI.saveConfigToDisk then UI.saveConfigToDisk(false) end
        end)

        createActionRow(prefGrp, 8, "Reset UI Window Scale to 100%", "Restores default 1.0x window size", "100% ↺", function()
            UI.uiScale = 1.0
            uiScaleSlider.setValue(100, true)
            notify("🎨 UI SCALE", "Restored UI Window Scale to 100%")
        end)

        -- Expose theme lookup so saved config can auto-apply theme
        UI.applyThemeByName = function(tName)
            for _, th in ipairs(THEMES) do
                if th.name == tName then
                    UI.currentThemeName = th.name
                    applyTheme(th)
                    break
                end
            end
        end
    end)()

