        freezeNonFriendsBtn.Size = UDim2.new(0, 106, 1, 0)
        freezeNonFriendsBtn.Position = UDim2.new(1, -106, 0, 0)
        freezeNonFriendsBtn.Text = "Freeze Non-Fr ❄️"
        freezeNonFriendsBtn.TextColor3 = Color3.new(1, 1, 1)
